import type { BankQuestion } from "@/lib/bank";

/** Pedagogy of Maths, EVS and Languages (Child Development & Pedagogy): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "cdp-pedagogy-subjects-1", "question": "In the Van Hiele model of geometric thinking, the basic level at which a child recognises shapes by their overall appearance (\"it looks like a door, so it is a rectangle\") is called:", "options": ["Visualisation", "Informal deduction", "Analysis", "Rigour"], "answer": 0, "explanation": "Level 0 (visualisation, or recognition) is based on the look of the whole shape. Analysis (Level 1) is the next level, where children describe a shape by its properties.", "difficulty": "easy", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-2", "question": "According to the NCF 2005 position on mathematics, the main goal of school mathematics is to develop the child's:", "options": ["speed in mechanical calculation", "memory for formulae", "ability to score well in board examinations", "ability to think mathematically (mathematisation of thought)"], "answer": 3, "explanation": "NCF 2005 names the 'mathematisation' of the child's thinking as the main goal, ahead of narrow goals such as computation speed or rote formulae.", "difficulty": "easy", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-3", "question": "As recommended by NCF 2005, Environmental Studies (EVS) for Classes III to V is an integrated subject that draws on:", "options": ["language and art education", "history and civics only", "science and mathematics only", "science, social science and environmental education"], "answer": 3, "explanation": "Primary EVS weaves together concerns of science, social science and environmental education instead of teaching them as separate disciplines.", "difficulty": "easy", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-4", "question": "The four basic language skills, in the order in which a child naturally acquires them, are:", "options": ["Listening, Speaking, Reading, Writing", "Reading, Writing, Listening, Speaking", "Listening, Reading, Speaking, Writing", "Speaking, Listening, Reading, Writing"], "answer": 0, "explanation": "Children listen before they speak, and learn to read before they write: the LSRW sequence. Receptive skills come before productive ones in each pair.", "difficulty": "easy", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-5", "question": "A Class II child writes 25 + 17 = 312. The error most likely shows that the child:", "options": ["does not know the number names up to 50", "cannot add single-digit numbers", "adds each column separately and writes the whole sum, without regrouping (carrying)", "has a reading disability"], "answer": 2, "explanation": "5 + 7 = 12 is written in full and 2 + 1 = 3 is written beside it, giving 312. The child adds digits correctly but has not grasped place value and carrying.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-6", "question": "Which is the most appropriate way to introduce fractions to Class III children?", "options": ["Writing fractions such as 1/2 and 1/4 on the board", "Giving worksheets on adding unlike fractions", "Defining the numerator and the denominator", "Sharing real objects such as a roti or a sheet of paper equally among children"], "answer": 3, "explanation": "Fractions grow out of the everyday experience of equal sharing. Concrete sharing should come before symbols and definitions.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-7", "question": "The NCERT EVS textbooks for Classes III to V, prepared after NCF 2005, are organised around themes such as:", "options": ["Family and Friends, Food, Shelter, Water, Travel, and Things We Make and Do", "Grammar, Composition and Literature", "Physics, Chemistry and Biology", "Ancient, Medieval and Modern History"], "answer": 0, "explanation": "The primary EVS syllabus uses six child-centred themes: Family and Friends (relationships, work and play, animals, plants), Food, Shelter, Water, Travel, and Things We Make and Do. It avoids subject divisions.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-8", "question": "A teacher asks children to run their eyes quickly over a passage only to find the year in which a dam was built. The reading strategy being practised is:", "options": ["scanning", "intensive reading", "extensive reading", "skimming"], "answer": 0, "explanation": "Scanning means searching a text quickly for one specific piece of information, such as a date or name. Skimming means reading quickly to get the general idea.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-9", "question": "Which classroom practice best reflects the multilingual approach recommended by NCF 2005?", "options": ["Teaching only in English from Class I so that children pick it up faster", "Translating every sentence of the textbook word for word", "Letting children use their home language to express ideas while they learn the school language", "Fining children who speak their mother tongue in school"], "answer": 2, "explanation": "NCF 2005 treats multilingualism as a resource. The child's home language is a bridge to the school language, not something to suppress.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-10", "question": "Using mathematical puzzles and games in a primary class mainly helps to:", "options": ["develop logical reasoning and reduce children's fear of mathematics", "replace the textbook entirely", "test how well children have memorised tables", "keep children busy when the teacher is absent"], "answer": 0, "explanation": "Puzzles and games make children reason, try strategies and enjoy mathematics, which counters maths anxiety. They add to the textbook; they do not replace it.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-11", "question": "Which approach to teaching reading begins with whole, meaningful texts such as stories and rhymes and treats reading as making meaning, not decoding isolated letters?", "options": ["Phonics approach", "Alphabetic method", "Whole language approach", "Grammar-translation method"], "answer": 2, "explanation": "The whole language approach starts from meaningful text and the child's experience. Phonics and the alphabetic method build up from sounds or letters.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-12", "question": "A Class IV teacher takes children to a nearby pond as part of an EVS lesson. The main value of this field visit is that it:", "options": ["gives children a break from studies", "replaces the need for any assessment", "helps the teacher finish the syllabus faster", "lets children observe and explore first-hand and connect learning with their surroundings"], "answer": 3, "explanation": "EVS aims to link classroom knowledge with the child's environment. First-hand observation and exploration on a field visit serve exactly that.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-13", "question": "According to the Van Hiele model, a child who explains that 'a square is also a rectangle, because it has four right angles and its opposite sides are equal' is at the level of:", "options": ["Visualisation", "Formal deduction", "Informal deduction", "Analysis"], "answer": 2, "explanation": "Seeing class inclusion (every square is a rectangle) by relating properties is Level 2, informal deduction (also called abstraction or ordering). At the analysis level, children list properties but treat squares and rectangles as separate.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-14", "question": "Many Class V children say that 0.25 is greater than 0.5 'because 25 is more than 5'. The most effective teaching response is to:", "options": ["ask them to memorise the rule 'compare digit by digit'", "use place-value charts or 10 × 10 grids to show tenths and hundredths visually", "give them more practice on the same kind of sums", "tell them they are being careless"], "answer": 1, "explanation": "The error comes from treating decimals as whole numbers, which is a misconception, not carelessness. Visual models of tenths and hundredths rebuild the concept. Drill or rules alone leave the misconception in place.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-15", "question": "According to NCF 2005, the concerns of EVS in Classes I and II should be:", "options": ["taught as formal science only", "woven into language and mathematics, without a separate EVS textbook", "left out of the curriculum entirely", "taught as a separate subject with its own textbook"], "answer": 1, "explanation": "NCF 2005 says that in Classes I and II the EVS themes should be integrated with language and mathematics. EVS becomes a separate subject from Class III.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-16", "question": "A Class III child insists that 'the sun moves around the earth, because I can see it moving across the sky'. In a constructivist EVS classroom, the teacher should treat this as:", "options": ["evidence of a learning disability", "a sign of low intelligence", "a wrong answer to be crossed out and corrected at once", "an alternative conception based on everyday experience, to be used as a starting point for exploration"], "answer": 3, "explanation": "Children build ideas from experience. Constructivist teaching draws out such alternative conceptions and uses activities and discussion to rebuild them, instead of dismissing them.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-17", "question": "Stephen Krashen's input hypothesis states that a second language is acquired when the learner:", "options": ["receives comprehensible input a little beyond the current level (i + 1)", "is corrected on every error at once", "is taught explicit grammar rules first", "repeats drills until they become habits"], "answer": 0, "explanation": "Krashen argued that acquisition happens through understanding messages slightly beyond one's level (i + 1). Drills and constant correction belong to behaviourist methods.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-18", "question": "A four-year-old says, 'I goed to the market and buyed two mangoes.' From the viewpoint of language development, this shows that the child:", "options": ["has a speech disorder that needs therapy", "should be corrected sharply so the error does not become fixed", "is overgeneralising a grammar rule (adding -ed), a normal sign of active language learning", "is copying incorrect adult speech"], "answer": 2, "explanation": "Overgeneralisation shows the child has worked out the past-tense rule and is applying it to irregular verbs too. Children never hear adults say 'goed', so it is not imitation. It is a normal stage.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-19", "question": "Which assessment task is most suitable for assessing the speaking skill of Class IV children?", "options": ["An oral narration or role-play assessed with a simple rubric", "A multiple-choice test on grammar", "A dictation exercise", "A fill-in-the-blanks worksheet"], "answer": 0, "explanation": "Speaking is a productive oral skill, so it is assessed through actual speaking tasks. The other options assess grammar knowledge, listening-and-writing or reading-and-writing.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-20", "question": "George Pólya's four steps of problem solving, in order, are:", "options": ["Devise a plan, understand the problem, look back, carry out the plan", "Guess, check, revise, conclude", "Understand the problem, devise a plan, carry out the plan, look back", "Read, memorise, calculate, check"], "answer": 2, "explanation": "Pólya's How to Solve It gives understand, plan, carry out and look back (review). The 'look back' step is often skipped in classrooms.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-21", "question": "To teach place value, a teacher first lets children bundle sticks into tens, then shows pictures of the bundles, and finally writes numerals such as 34. This sequence follows:", "options": ["the Van Hiele levels of geometric thought", "Piaget's idea of conservation", "Bruner's enactive, iconic and symbolic modes of representation", "Kohlberg's stages of moral reasoning"], "answer": 2, "explanation": "Handling sticks is enactive, pictures are iconic and numerals are symbolic. This concrete–pictorial–abstract progression comes from Jerome Bruner.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-22", "question": "The idea of 'language across the curriculum' means that:", "options": ["every subject class is also a language class, where children learn the vocabulary and ways of expression of that subject", "children should study as many languages as possible", "English should be the medium for all subjects", "language should be taught only in the language period"], "answer": 0, "explanation": "Language and learning are inseparable. In a science or mathematics lesson, children also learn to describe, explain and argue in the language of that subject.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-23", "question": "In mathematics pedagogy, 'mathematical communication' refers to children's ability to:", "options": ["talk freely during the mathematics period", "recite multiplication tables aloud", "write answers neatly in the notebook", "express, explain and justify mathematical ideas using precise language and symbols"], "answer": 3, "explanation": "Mathematical communication means explaining one's reasoning, using correct terms and symbols, and justifying solutions to others. It is not just talking or neat writing.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-24", "question": "NEP 2020 recommends that, wherever possible, the medium of instruction until at least Grade 5, and preferably till Grade 8 and beyond, should be:", "options": ["Hindi", "Sanskrit", "the home language, mother tongue, local language or regional language", "English"], "answer": 2, "explanation": "NEP 2020 (para 4.11) recommends the home language, mother tongue or local/regional language as the medium of instruction at least till Grade 5, preferably till Grade 8 and beyond.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-25", "question": "How many of the following match the NCF 2005 position on school mathematics? I. The focus should shift from procedures to problem solving and mathematisation. II. Children should see mathematics as something to talk about, communicate and discuss. III. Mathematics should be taught only to children who show an aptitude for it. IV. Algorithms should be taught before children understand the concepts behind them.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II reflect NCF 2005, which wants children to enjoy, discuss and reason about mathematics. III goes against its 'mathematics for all' view, and IV goes against its focus on understanding. So only two match.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-26", "question": "How many of the following statements about the National Curriculum Framework for School Education (NCF-SE) 2023 are correct? I. The Foundational Stage covers ages 3 to 8 (three years of pre-school plus Grades 1 and 2). II. Board examinations are to be offered at least twice a year. III. In Grades 9 and 10 students study three languages, at least two of which are native to India. IV. In Grades 11 and 12 students must study three languages.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: in Grades 11 and 12, NCF-SE 2023 requires two languages, at least one of them native to India. So only three are correct.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-27", "question": "Match the teaching aid with its main use in mathematics: 1. Napier's bones 2. Geoboard 3. Dienes (base-ten) blocks 4. Tangram; a. Place value b. Multiplication c. Making figures from seven geometric pieces d. Area and perimeter using pegs and rubber bands", "options": ["1-a, 2-d, 3-b, 4-c", "1-d, 2-b, 3-c, 4-a", "1-b, 2-c, 3-a, 4-d", "1-b, 2-d, 3-a, 4-c"], "answer": 3, "explanation": "Napier's bones are rods for multiplication. A geoboard uses pegs and rubber bands to explore area and perimeter. Dienes blocks (units, longs, flats) model place value. A tangram has seven pieces for composing figures.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-28", "question": "Assertion (A): Teachers should encourage children to estimate an answer before working it out. Reason (R): Estimation helps children judge whether an answer is reasonable and builds number sense.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true, and R explains A: estimating first gives a benchmark for spotting unreasonable answers and strengthens number sense, which is why it is encouraged.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-29", "question": "Assertion (A): Correcting every error a child makes while speaking a new language is the best way to ensure accuracy. Reason (R): Errors are a natural part of language learning and reveal the child's developing ideas about how the language works.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "R is true: errors are windows into the learner's developing grammar. A is false, because constant correction discourages children from speaking and harms fluency. Errors call for selective, sensitive feedback.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-30", "question": "How many of the following statements about EVS at the primary level, as envisaged in NCF 2005, are correct? I. EVS is taught as a separate subject with its own textbook from Class I onwards. II. It aims to connect children's learning in school with their life outside school. III. It is to be assessed mainly through written tests of definitions. IV. Its themes are presented from the child's point of view rather than through subject divisions.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "II and IV are correct. I is wrong, because EVS is a separate subject only from Class III (it is integrated with language and maths in Classes I–II). III is wrong, because NCF 2005 wants continuous assessment through observation, activities and projects, not tests of definitions. So only two.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-31", "question": "Which of the following is NOT a feature of the communicative approach to language teaching?", "options": ["A focus on meaning and fluency", "Insisting on grammatical accuracy through mechanical drills before any real use of the language", "Using real-life tasks such as asking for directions", "Plenty of pair and group work"], "answer": 1, "explanation": "The communicative approach puts meaningful use first, through real tasks, interaction and fluency. Mechanical drilling for accuracy before use belongs to the structural or audio-lingual methods.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-32", "question": "While counting six marbles, a child says 'one, two, three, four, five, six, seven' in the correct order but touches one marble twice. Which counting principle has the child not yet mastered?", "options": ["One-to-one correspondence", "Cardinality", "Stable order", "Order irrelevance"], "answer": 0, "explanation": "Each object must get exactly one number word (one-to-one correspondence), and touching a marble twice breaks this. The number words came in the right order, so the stable-order principle is intact.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-33", "question": "After correctly counting seven pencils, a child is asked 'So how many pencils are there?' and starts counting all over again instead of answering 'seven'. The child has not yet grasped the principle of:", "options": ["cardinality", "abstraction", "one-to-one correspondence", "stable order"], "answer": 0, "explanation": "Cardinality means the last number word said gives the size of the whole set. A child who recounts has not linked 'seven' to the total, even though the counting itself was correct.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-34", "question": "Phonemic awareness is best shown when a child can:", "options": ["copy words neatly from the board", "say that 'cat' without its first sound /k/ becomes 'at'", "name the letter C when it is shown", "read a sentence aloud fluently"], "answer": 1, "explanation": "Phonemic awareness is the ability to hear and handle individual sounds in spoken words, e.g. taking away the first sound. Naming letters is letter knowledge, and fluent reading is a later skill.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-35", "question": "Which question best assesses a Class V child's conceptual understanding of fractions rather than procedural skill?", "options": ["Without calculating, explain why 3/4 is greater than 3/5", "Convert 3/4 into a decimal", "Add 3/4 and 3/5", "Find the LCM of 4 and 5"], "answer": 0, "explanation": "Explaining that the same number of larger parts (quarters are bigger than fifths) makes a larger fraction needs understanding. The other tasks can be done by following a learned procedure.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-36", "question": "An EVS chapter for Class IV asks children: 'Who cooks food in your family? Who fetches water? Why?' The main purpose of such questions is to:", "options": ["test children's memory of family members' names", "teach children recipes", "help children reflect on gender roles and the division of work in their own families", "collect household data for the school records"], "answer": 2, "explanation": "Primary EVS uses open questions from the child's own life to raise social issues such as gender, work and equity, so children think critically about everyday roles.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-37", "question": "How many of the following statements about NEP 2020 are correct? I. It gives the highest priority to achieving universal foundational literacy and numeracy in primary school by 2025. II. The NIPUN Bharat mission was launched to work towards foundational literacy and numeracy goals. III. It keeps the three-language formula but adds flexibility, saying no language will be imposed on any state. IV. It makes English the compulsory medium of instruction from Grade 1.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct (NIPUN Bharat was launched in 2021 to pursue FLN). IV is wrong, because NEP 2020 prefers the mother tongue or regional language as the medium of instruction in the early grades. So only three.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-38", "question": "How many of the following statements about teaching reading and writing in the primary grades are correct? I. The aim of reading instruction is reading with comprehension, not just decoding. II. Using children's literature in class supports language development. III. A print-rich classroom environment supports emergent literacy. IV. A child's home language is a resource for learning the school language.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four reflect current language pedagogy (NCF 2005, NCF-FS 2022 and NEP 2020). Reading is meaning-making, children's literature and print-rich classrooms support literacy, and the home language is a bridge, not a barrier.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-39", "question": "Which sequence is most appropriate for teaching the measurement of length in the primary classes?", "options": ["The need for a standard unit, then using a ruler, then direct comparison, then non-standard units", "Non-standard units, then using a ruler, then direct comparison, then the need for a standard unit", "Direct comparison of objects, then non-standard units (hand span, pencil), then the need for a standard unit, then using a ruler", "Using a ruler, then non-standard units, then direct comparison, then the need for a standard unit"], "answer": 2, "explanation": "Children first compare lengths directly (longer or shorter), then measure with body or object units. They see that different hand spans give different answers, which creates the need for a standard unit, and only then use the ruler.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-40", "question": "Which of the following is NOT one of the five guiding principles of NCF 2005?", "options": ["Making board examinations compulsory at the end of Class VIII", "Making examinations more flexible and integrated with classroom life", "Moving learning away from rote methods", "Connecting knowledge to life outside the school"], "answer": 0, "explanation": "The five guiding principles are: connecting knowledge to life outside school, moving away from rote learning, enriching the curriculum beyond textbooks, making examinations flexible and integrated with classroom life, and nurturing an overriding identity informed by caring concerns within the democratic polity. A Class VIII board exam is not one of them.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-41", "question": "The NCERT textbooks for Environmental Studies (Classes III to V) are titled:", "options": ["Looking Around", "Rimjhim", "Math-Magic", "Marigold"], "answer": 0, "explanation": "“Looking Around” is the NCERT EVS series. Rimjhim is the Hindi reader, Math-Magic the mathematics series and Marigold the English reader for the primary classes.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-42", "question": "A specific learning disability that mainly affects understanding numbers and doing calculations is called:", "options": ["Dyslexia", "Dysgraphia", "Dyscalculia", "Dyspraxia"], "answer": 2, "explanation": "Dyscalculia affects number sense and calculation. Dyslexia affects reading, dysgraphia writing, and dyspraxia motor coordination.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-43", "question": "Which is the most suitable way to begin addition with Class I children?", "options": ["Memorising addition tables", "Writing long columns of sums on the board", "Practising abstract symbols only", "Combining and counting real objects such as pebbles and seeds"], "answer": 3, "explanation": "Young children are at a concrete stage; joining real collections and counting gives meaning to “adding” before symbols are introduced.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-44", "question": "A Class III child writes 52 − 27 = 35. What is the most likely reason for this error?", "options": ["Carelessness in copying the numbers", "In each column the child subtracts the smaller digit from the larger, ignoring regrouping", "The child does not know subtraction facts up to 10", "The child has added instead of subtracted"], "answer": 1, "explanation": "In the ones place the child did 7 − 2 = 5 instead of regrouping, then 5 − 2 = 3. This systematic “smaller-from-larger” error shows a gap in understanding place value and borrowing.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-45", "question": "A teacher shows children many triangles, has them measure the angles, and helps them conclude that the angles of a triangle add up to 180°. This is the:", "options": ["Deductive method", "Lecture method", "Inductive method", "Analytic method"], "answer": 2, "explanation": "The inductive method moves from specific examples to a general rule, which suits young learners. The deductive method starts with the rule and then applies it.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-46", "question": "Which of these is NOT one of the six themes around which the NCERT EVS books for Classes III–V are organised?", "options": ["Water", "Travel", "Things We Make and Do", "Our Solar System"], "answer": 3, "explanation": "The six themes are Family and Friends, Food, Shelter, Water, Travel, and Things We Make and Do. The books deliberately avoid organising content by disciplines such as astronomy.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-47", "question": "In the 5E model of inquiry-based teaching used in science and EVS, the phases occur in which order?", "options": ["Engage, Explore, Explain, Elaborate, Evaluate", "Explain, Engage, Explore, Evaluate, Elaborate", "Explore, Engage, Explain, Evaluate, Elaborate", "Engage, Explain, Explore, Elaborate, Evaluate"], "answer": 0, "explanation": "Children are first engaged by a question, then explore, then explain what they found, elaborate by applying it, and finally evaluate their understanding.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-48", "question": "The project method of teaching, built on Dewey's ideas of learning by doing, was developed by:", "options": ["Maria Montessori", "W. H. Kilpatrick", "H. E. Armstrong", "Friedrich Froebel"], "answer": 1, "explanation": "William Heard Kilpatrick proposed the project method (1918). Armstrong is linked with the heuristic method and Froebel with the kindergarten.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-49", "question": "Richard Skemp distinguished “relational understanding” from “instrumental understanding”. Relational understanding means:", "options": ["Knowing a rule and how to apply it quickly", "Knowing both what to do and why it works", "Memorising formulae through repeated practice", "Relating mathematics only to daily life examples"], "answer": 1, "explanation": "Instrumental understanding is “rules without reasons”; relational understanding connects procedures to the underlying concepts, so it transfers better to new problems.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-50", "question": "To study the theme “Water” in Class IV, which activity best fits the approach of NCF 2005?", "options": ["Copying the definition of the water cycle five times", "Reading the chapter aloud and answering textbook questions", "Surveying water sources in the neighbourhood and discussing who fetches water and how far", "Memorising the names of major rivers of the world"], "answer": 2, "explanation": "A local survey links the theme to children's own lives, involves observation and recording, and raises issues of access and equity, as NCF 2005 recommends.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-51", "question": "Zoltan Dienes's “perceptual variability” (multiple embodiment) principle means that a mathematical concept should be:", "options": ["Taught through only one well-chosen model", "Presented through several different concrete materials and situations", "Introduced first as a formal definition", "Practised until answers become automatic"], "answer": 1, "explanation": "Meeting the same idea, such as place value, in sticks, beads and blocks helps children abstract what is common and not tie the concept to one material.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-52", "question": "Many children think that multiplying always gives a bigger number, so they are puzzled that 1/2 × 1/4 = 1/8. The best teaching response is to:", "options": ["Tell them the rule and ask them to memorise it", "Use area models to show that taking a part of a part gives a smaller part", "Avoid fraction multiplication until Class VIII", "Give a large number of similar sums for drill"], "answer": 1, "explanation": "The belief comes from experience with whole numbers. An area or paper-folding model shows that “half of a quarter” is smaller than both, correcting the misconception through meaning.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-53", "question": "A child correctly lists the properties of a square (four equal sides, four right angles) but insists that a square is not a rectangle. According to Van Hiele, the child is at the level of:", "options": ["Visualisation", "Analysis", "Informal deduction", "Rigour"], "answer": 1, "explanation": "At the analysis level children describe shapes by their properties but do not yet see relationships between classes of shapes, which comes at informal deduction.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-54", "question": "The heuristic method, in which the learner is put in the position of a discoverer, was advocated by:", "options": ["H. E. Armstrong", "W. H. Kilpatrick", "J. S. Bruner", "B. F. Skinner"], "answer": 0, "explanation": "Henry Edward Armstrong promoted the heuristic method in science teaching. Bruner is linked with discovery learning more generally and Skinner with programmed instruction.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-55", "question": "Concept maps, used in EVS and science to show how ideas are linked, were developed by:", "options": ["Jean Piaget", "Joseph Novak", "Howard Gardner", "Benjamin Bloom"], "answer": 1, "explanation": "Joseph Novak developed concept mapping in the 1970s, building on Ausubel's idea that meaningful learning links new ideas to existing knowledge.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-56", "question": "Which of these is an open-ended task in mathematics?", "options": ["What is 12 + 8?", "Find as many pairs of numbers as you can whose sum is 20.", "Write the multiplication table of 4.", "Copy the numbers from 1 to 50."], "answer": 1, "explanation": "An open-ended task has many correct answers and lets children use different strategies and reasoning. The other tasks have a single fixed answer.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-57", "question": "NCERT's indicators for assessing learning in EVS include all of the following EXCEPT:", "options": ["Observation and recording", "Classification", "Concern for justice and equality", "Reproducing textbook definitions word for word"], "answer": 3, "explanation": "The EVS indicators include observation and recording, discussion, expression, explanation, classification, questioning, analysis, experimentation, concern for justice and equality, and cooperation. Rote reproduction is not an indicator.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-58", "question": "In a geometry proof, working backwards from what is to be proved towards what is already known is called the:", "options": ["Synthetic method", "Inductive method", "Analytic method", "Laboratory method"], "answer": 2, "explanation": "The analytic method goes from the unknown to the known and helps children discover the proof. The synthetic method presents the proof from known facts to the conclusion.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-59", "question": "Which is a major limitation of using the deductive method alone with young children in mathematics?", "options": ["It takes too long to complete the syllabus", "It may lead to memorising formulae without understanding where they come from", "It needs costly laboratory equipment", "It cannot be used for geometry"], "answer": 1, "explanation": "Starting with a ready-made rule is quick, but children may apply it mechanically. Combining it with the inductive method builds understanding first.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-60", "question": "Activities in which children extend number and shape patterns (2, 4, 6, 8, …) mainly help them to develop:", "options": ["Speed in written computation", "Generalisation and early algebraic thinking", "Neat handwriting of numerals", "Memory of multiplication tables"], "answer": 1, "explanation": "Recognising and describing a rule behind a pattern is the root of algebraic thinking; NCF 2005 gives patterns a place from the early grades.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-61", "question": "Assertion (A): EVS in the primary classes should begin from the child's immediate surroundings. Reason (R): Children construct new knowledge by linking new experiences to what they already know.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Starting from home, family and neighbourhood gives children a base of experience to build on, in line with constructivism.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-62", "question": "Consider the following statements about the NCERT EVS books for Classes III–V: 1. They follow a thematic organisation rather than separate science and social science chapters. 2. Their exercises are designed mainly for rote recall of definitions. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. The exercises ask children to observe, discuss, find out from elders and express their views, not to reproduce definitions.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-63", "question": "Arrange these Van Hiele levels in the order in which they develop: 1. Deduction 2. Analysis 3. Rigour 4. Informal deduction", "options": ["2, 4, 1, 3", "2, 1, 4, 3", "4, 2, 1, 3", "2, 4, 3, 1"], "answer": 0, "explanation": "After visualisation come analysis, informal deduction (abstraction), formal deduction and finally rigour.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-64", "question": "How many of these statements about the NIPUN Bharat Mission are correct? I. It was launched in 2021. II. It aims for every child to achieve foundational literacy and numeracy by the end of Grade 3. III. Its target year is 2026–27. IV. It covers children in the age group of 3 to 9 years.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. NIPUN Bharat implements the NEP 2020 priority on foundational literacy and numeracy.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-65", "question": "Consider the following statements: 1. Vidya Pravesh is a three-month, play-based school preparation module for children entering Grade 1. 2. It was launched as part of implementing NEP 2020. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Vidya Pravesh eases the move to school through play, stories and activities before formal instruction.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-66", "question": "Assertion (A): Children should be allowed to use their own informal strategies for addition before the standard algorithm is taught. Reason (R): Standard algorithms are always inefficient and should be avoided.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: invented strategies build number sense and make the algorithm meaningful later. R is false: standard algorithms are efficient tools once understood.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-67", "question": "A Class V child writes 1/2 + 1/3 = 2/5. Which response best addresses the misconception?", "options": ["Make the child repeat the rule for finding the LCM", "Use fraction strips or area models to show that halves and thirds must be changed to equal-sized parts before adding", "Mark the answer wrong and move on", "Give twenty similar sums for homework"], "answer": 1, "explanation": "The child is treating numerators and denominators as separate whole numbers. Models show why common-sized parts (sixths) are needed, giving meaning to the procedure.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-68", "question": "Which question in an EVS lesson on houses most encourages higher-order thinking?", "options": ["Name two types of houses.", "What is a house made of mud called?", "Why do you think many houses in Rajasthan have thick walls and small windows?", "Which material is used for roofs in your textbook picture?"], "answer": 2, "explanation": "Asking “why” makes children link climate and building design, which calls for reasoning and inference rather than recall.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-69", "question": "Consider the following statements: 1. Formative assessment in mathematics can include observing the strategies children use during group work. 2. Summative assessment results should be used to label children as slow learners. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. Assessment is meant to improve teaching and learning; labelling children harms their confidence and is discouraged by NCF 2005.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-70", "question": "In the grammar-translation method of teaching a language:", "options": ["Only the target language is used in class", "Learning happens through drills and habit formation", "Children learn through real-life communicative tasks", "Grammar rules are taught explicitly and texts are translated using the mother tongue"], "answer": 3, "explanation": "Grammar-translation relies on rules, vocabulary lists and translation, with little speaking practice. The direct method bans translation; audio-lingual uses drills.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-71", "question": "A child who has persistent difficulty in forming letters, spacing words and writing legibly may have:", "options": ["Dysgraphia", "Dyscalculia", "Aphasia", "Dyslexia"], "answer": 0, "explanation": "Dysgraphia is a learning disability affecting handwriting and written expression. Dyslexia affects reading; aphasia is loss of language ability, usually after brain injury.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-72", "question": "A teacher asks children to read a passage quickly to get its general idea before reading it closely. This reading strategy is called:", "options": ["Scanning", "Intensive reading", "Loud reading", "Skimming"], "answer": 3, "explanation": "Skimming is quick reading for the gist; scanning is searching for a specific detail such as a name or date.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-73", "question": "Noam Chomsky held that children learn language easily because they are born with:", "options": ["A blank slate shaped wholly by reinforcement", "A Language Acquisition Device", "A fixed vocabulary of a few hundred words", "An ability that appears only after schooling"], "answer": 1, "explanation": "Chomsky argued for an innate Language Acquisition Device and a universal grammar, against Skinner's view that language is learnt only through imitation and reinforcement.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-74", "question": "According to B. F. Skinner, children acquire language mainly through:", "options": ["An innate universal grammar", "Social interaction within the zone of proximal development", "Imitation and reinforcement", "Biological maturation alone"], "answer": 2, "explanation": "Skinner's behaviourist view (Verbal Behavior, 1957) explains language as habits shaped by reinforcement. Chomsky criticised it for not explaining children's novel sentences.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-75", "question": "A test in which children fill in words deleted at regular intervals from a passage is called a:", "options": ["Dictation test", "Cloze test", "True–false test", "Matching test"], "answer": 1, "explanation": "A cloze test checks comprehension and language knowledge, since filling the gaps needs understanding of the context and grammar.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-76", "question": "In the process approach to writing, which sequence is correct?", "options": ["Editing, drafting, brainstorming, revising", "Drafting, brainstorming, editing, revising", "Brainstorming, editing, drafting, revising", "Brainstorming, drafting, revising, editing"], "answer": 3, "explanation": "Writers first generate ideas, then write a draft, revise its content and organisation, and finally edit for language and mechanics before publishing.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-77", "question": "The phonics approach to teaching reading focuses on:", "options": ["Guessing words from pictures only", "Memorising whole texts", "Teaching the relationship between letters and the sounds they stand for", "Reading silently from the start"], "answer": 2, "explanation": "Phonics teaches sound–symbol correspondence so that children can decode new words. It works best alongside meaningful reading, not in isolation.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-78", "question": "Which is the most effective way to build the vocabulary of young learners?", "options": ["Making them meet new words repeatedly in stories, songs and conversation", "Giving lists of words with meanings to memorise", "Testing spellings every day", "Asking them to copy dictionary entries"], "answer": 0, "explanation": "Words are learnt best in meaningful context with repeated exposure; isolated lists are quickly forgotten.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-79", "question": "Who held that thought and language develop from separate roots and come together at about the age of two, when thought becomes verbal and speech becomes rational?", "options": ["Jean Piaget", "Noam Chomsky", "B. F. Skinner", "Lev Vygotsky"], "answer": 3, "explanation": "Vygotsky (Thought and Language) described this meeting of thought and speech. Piaget saw language as reflecting thought, and Chomsky stressed innate grammar.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-80", "question": "According to Krashen's affective filter hypothesis, a learner's acquisition of a second language is blocked mainly by:", "options": ["Too much comprehensible input", "Anxiety, low motivation and low self-confidence", "Learning grammar after vocabulary", "Using the mother tongue at home"], "answer": 1, "explanation": "A high affective filter keeps input from being acquired. A relaxed classroom where mistakes are accepted lowers the filter.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-81", "question": "Consider the following statements based on Krashen's theory: 1. Acquisition is a subconscious process similar to how children pick up their first language. 2. Learning refers to conscious knowledge of the rules of a language. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Krashen argued that fluency comes mainly from acquisition, while consciously learnt rules mostly serve as a monitor.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-82", "question": "After a story, which question checks inferential comprehension?", "options": ["What was the name of the old man?", "Where did the old man live?", "How many goats did the old man have?", "Why do you think the old man smiled at the end?"], "answer": 3, "explanation": "Inferential questions need children to read between the lines. The others are literal questions whose answers are stated in the text.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-83", "question": "The three-language formula was recommended by the Kothari Commission and adopted in the:", "options": ["National Policy on Education, 1968", "National Policy on Education, 1986", "Right to Education Act, 2009", "National Curriculum Framework, 2005"], "answer": 0, "explanation": "The Education Commission (1964–66) recommended it and the 1968 policy adopted it. NCF 2005 and NEP 2020 reaffirmed it with flexibility.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-84", "question": "Which Article of the Constitution asks every State to provide facilities for instruction in the mother tongue at the primary stage to children of linguistic minority groups?", "options": ["Article 45", "Article 29", "Article 21A", "Article 350A"], "answer": 3, "explanation": "Article 350A, added in 1956, deals with mother-tongue instruction. Article 29 protects culture and language, and Article 21A is the right to education.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-85", "question": "A Class I teacher labels objects in the room, displays children's names, charts and posters at their eye level. The main purpose is to:", "options": ["Decorate the classroom for inspections", "Create a print-rich environment that supports emergent literacy", "Make children copy the labels as handwriting practice", "Test children's spelling"], "answer": 1, "explanation": "Seeing meaningful print around them helps children notice that print carries meaning and supports early reading and writing.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-86", "question": "“Big Books” in early-grade classrooms are mainly used for:", "options": ["Silent individual reading", "Shared reading, in which the whole class can see the text and pictures while the teacher reads", "Testing spellings", "Copying text into notebooks"], "answer": 1, "explanation": "Big Books let the teacher model reading, point to words and invite predictions, so children join in reading together.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-87", "question": "A child often reverses letters such as b and d. Which remedial approach is most suitable?", "options": ["Making the child write each letter a hundred times", "Scolding the child for carelessness", "A multisensory approach, such as tracing letters in sand while saying their sounds", "Moving the child to a lower class"], "answer": 2, "explanation": "Multisensory methods link sight, sound, movement and touch, which helps children with reversal difficulties; punishment and drills do not.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-88", "question": "Which task is most suitable for assessing the listening skill of Class III children?", "options": ["Copying a paragraph from the board", "Writing an essay on “My School”", "Reading a passage aloud", "Listening to a short announcement and answering questions about it"], "answer": 3, "explanation": "A listening task needs a spoken input and a response that shows understanding. The other tasks assess writing or reading.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-89", "question": "While reading a story aloud, a teacher stops and asks, “What do you think will happen next?” This mainly develops children's:", "options": ["Handwriting", "Ability to predict and engage actively with the text", "Memory for spelling", "Speed of silent reading"], "answer": 1, "explanation": "Predicting makes children use clues from the text and their own experience, which builds active comprehension.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-90", "question": "Consider the following statements based on Krashen's theory: 1. The monitor hypothesis says consciously learnt rules act as an editor on what the learner produces. 2. The natural order hypothesis says grammatical structures are acquired in a broadly predictable order. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Together with the input, acquisition–learning and affective filter hypotheses, these make up Krashen's five hypotheses.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-91", "question": "Match the language teaching method with its feature: A. Grammar-translation B. Direct method C. Audio-lingual method D. Communicative approach — 1. Drills and habit formation 2. Meaningful interaction through real-life tasks 3. Translation and explicit rules 4. Target language only, no translation", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "Grammar-translation uses translation and rules, the direct method avoids the mother tongue, the audio-lingual method uses behaviourist drills, and the communicative approach stresses meaningful use.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-92", "question": "How many of these statements about language policy in education are correct? I. The Kothari Commission recommended the three-language formula. II. Article 350A concerns mother-tongue instruction at the primary stage. III. Article 351 directs the Union to promote the spread of Hindi. IV. NEP 2020 makes it compulsory for every State to teach a particular language.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. NEP 2020 states that no language will be imposed on any State; the choice of languages rests with States and students.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-93", "question": "Arrange these levels of reading comprehension in increasing order of cognitive demand: 1. Evaluative (critical) 2. Literal 3. Inferential", "options": ["2, 3, 1", "3, 2, 1", "2, 1, 3", "1, 3, 2"], "answer": 0, "explanation": "Literal comprehension recalls what is stated, inferential reads between the lines, and evaluative comprehension judges the text against one's own values and knowledge.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-94", "question": "Consider the following statements: 1. Dictation can assess listening and writing together. 2. A cloze test assesses only spelling. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. A cloze test checks comprehension, vocabulary and grammar, since the missing words must fit the meaning of the passage.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-95", "question": "Assertion (A): Children should learn the whole alphabet in order before they are exposed to any meaningful text. Reason (R): Reading is mainly the decoding of letters and has little to do with meaning.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "Both A and R are false"], "answer": 3, "explanation": "Both are false. Reading is making meaning from text; children benefit from stories and print from the start, with decoding skills taught alongside, not before.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-96", "question": "A Class II child reads a story aloud fluently but cannot answer simple questions about it. What should the teacher focus on?", "options": ["More practice in loud, fast reading", "Comprehension through discussion, questioning and relating the story to the child's experience", "Spelling tests on the story's words", "Copying the story into the notebook"], "answer": 1, "explanation": "The child can decode but is not making meaning. Talking about the story, predicting and connecting it to life build comprehension.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-97", "question": "Which classroom arrangement best supports a child with a hearing impairment in a language class?", "options": ["Seating the child at the back to avoid distraction", "Speaking faster so the lesson is covered", "Turning to the board while speaking", "Seating the child where the teacher's face is clearly visible and using visual aids and gestures"], "answer": 3, "explanation": "Seeing the speaker's face helps lip-reading, and visual support makes content accessible, in line with inclusive education under the RPwD Act, 2016.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-98", "question": "How many of these statements about the process approach to writing are correct? I. It focuses on the stages through which a piece of writing is composed. II. Feedback from peers is valued. III. Only the final product is assessed. IV. Drafts are revised before the final version.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. The process approach also values and assesses drafts and revisions, not just the finished product.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-99", "question": "Consider the following statements: 1. Phonemic awareness is an oral skill and can be developed without print, for example through rhymes and sound games. 2. Phonics connects sounds with written letters. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Phonemic awareness (hearing and playing with sounds) usually comes first and supports later phonics instruction.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-100", "question": "A teacher lets children answer in their home language during an English lesson and then helps them express the same idea in English. This practice is best described as:", "options": ["Using the mother tongue as a resource for learning a new language", "Lowering the standard of English teaching", "The grammar-translation method", "Avoiding the target language"], "answer": 0, "explanation": "NCF 2005 treats multilingualism as a resource; building on the home language lets children participate and gradually move to English.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-101","question":"A Class 6 child writes 0.3 × 0.2 = 0.6. Which teaching response best addresses the misconception behind this answer?","options":["Tell the child to count the total decimal places and practise twenty such sums","Use a 10 × 10 grid to show 3 tenths of 2 tenths as 6 small squares out of 100, and ask whether the product of two numbers less than 1 can exceed either of them","Explain that the decimal point in a product always stays in the same place as in the numbers","Convert both numbers to whole numbers, multiply, and ignore the decimal point"],"answer":1,"explanation":"The child is treating decimal multiplication like addition of tenths. An area model shows the answer is 6 hundredths (0.06) and builds the reasoning that taking part of a part gives something smaller; a rule alone leaves the misconception intact.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-102","question":"Asked to fill the box in 5 + ☐ = 12, several Class 2 children write 17. The most likely reason, and the best response, is that the children:","options":["Cannot add, so they need more addition drill","Did not read the question, so they need to be told to be careful","See ‘=’ as a signal to write the answer of the operation on its left, so the teacher should use a balance or number sentences like 12 = 5 + 7 to build ‘=’ as ‘is the same as’","Are confused by the box, so it should be replaced by a blank line"],"answer":2,"explanation":"Children often hold an operational view of the equals sign (‘do the sum’). Activities with balances and varied forms of equations develop the relational meaning needed for later algebra.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-103","question":"A Class 4 child insists that 1/8 is bigger than 1/6 ‘because 8 is bigger than 6’. Which activity is most likely to change this idea?","options":["Asking the child to share one roti equally among 6 friends and another identical roti among 8 friends, and compare the size of each share","Making the child write ‘1/6 > 1/8’ ten times","Teaching the rule ‘bigger denominator, smaller fraction’ to be memorised","Converting both fractions to decimals with a calculator"],"answer":0,"explanation":"The child is applying whole-number ordering to fractions. Fair-sharing experience shows that more sharers make smaller pieces, giving meaning to the rule instead of a memorised statement.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-104","question":"Many Class 5 children believe that two rectangles with the same perimeter must have the same area. Which activity best challenges this belief?","options":["Giving the formulas for perimeter and area to memorise","Asking them to find the area of one 6 cm × 6 cm square","Telling them that area and perimeter are different","Asking them to make different rectangles from a 24 cm loop of string on squared paper and compare the areas they enclose"],"answer":3,"explanation":"With a perimeter of 24 cm they can make 1 × 11 (area 11), 2 × 10 (area 20) or 6 × 6 (area 36): same perimeter, very different areas. Discovering this first-hand changes the belief.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-105","question":"A child measures a pencil by placing its end at the ‘1’ mark of a ruler and reads ‘8 cm’ at the other end; the pencil is actually 7 cm long. The child most likely:","options":["Has poor eyesight and needs a ruler with larger numbers","Thinks length is read by counting marks or reading the end number, rather than counting the unit spaces between start and end","Does not know the numbers up to 10","Has been taught the wrong length of a centimetre"],"answer":1,"explanation":"Measuring means counting units (spaces) from a zero point; children who see the ruler as a list of numbers make this error. Measuring with unit strips or ‘broken rulers’ builds the idea.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-106","question":"A teacher first lets children measure the length of the classroom with their own footsteps and hand spans, and only later introduces the metre. The main purpose is to:","options":["Make children realise the need for a standard unit when their measurements of the same length differ","Avoid teaching standard units altogether in primary classes","Save the cost of buying metre scales","Show that body parts are more accurate than rulers"],"answer":0,"explanation":"When different children get different numbers of hand spans for the same length, they see why a common, standard unit is needed; this gives meaning to the metre.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-107","question":"Which response by a Class 4 child shows the best number sense?","options":["Writing 99 + 47 in columns and carrying carefully","Counting on from 99 one by one up to 146","Saying ‘99 + 47 is the same as 100 + 46, so it’s 146’","Using a calculator to check 99 + 47"],"answer":2,"explanation":"Number sense is flexible understanding of numbers and their relationships; seeing 99 as 1 less than 100 and adjusting shows it. The column method is correct but procedural.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-108","question":"A child works out 298 + 165 by thinking ‘300 + 165 = 465, and I added 2 too many, so 463.’ This mental strategy is called:","options":["Partitioning by place value","Counting on in ones","Using the standard algorithm","Compensation"],"answer":3,"explanation":"Compensation rounds one number to a friendly value and then adjusts for the change. It reflects a sound understanding of how numbers can be rearranged.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-109","question":"Squares are made in a row with matchsticks: 1 square needs 4 sticks, 2 squares need 7, 3 squares need 10. A child says 10 squares need 40 sticks. The child’s error and the correct number are:","options":["The child counted each square separately, ignoring shared sides; 31 sticks","The child added 3 each time; 30 sticks","The child multiplied correctly; 40 sticks is right","The child forgot the first stick; 41 sticks"],"answer":0,"explanation":"After the first square each new square needs only 3 sticks, so n squares need 3n + 1 = 31. Asking children to explain the rule from the figure moves them from counting to algebraic generalisation.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-110","question":"In a pictograph where one 🙂 stands for 5 children, a Class 3 child reads 4 symbols as ‘4 children like mangoes’. The child has difficulty with:","options":["Counting up to 5","Collecting data through a tally","Interpreting the key (scale) of the pictograph","Drawing the symbols neatly"],"answer":2,"explanation":"The child reads each symbol as one item. Building pictographs themselves with a one-to-many key helps children understand scale (4 symbols × 5 = 20 children).","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-111","question":"Shown a triangle standing on one of its corners, several Class 2 children say, ‘That is not a triangle, it is upside down.’ The best teaching response is to:","options":["Tell them that it is a triangle and move on","Avoid showing shapes in unusual positions until higher classes","Teach the formal definition of a triangle","Show and let them make many triangles of different sizes, shapes and orientations, and discuss what makes all of them triangles"],"answer":3,"explanation":"Children’s idea of a shape is often tied to a prototype seen in books. Varied examples and attention to defining properties (three straight sides, closed) broaden the concept.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-112","question":"Shown two angles of the same size, one drawn with long arms and one with short arms, a child says the one with longer arms is bigger. Which activity best addresses this?","options":["Making the child memorise that an angle is measured in degrees","Using a paper fan or two hinged strips to show that the angle is the amount of turn between the arms, and that lengthening the arms does not change it","Asking the child to draw the arms more carefully","Telling the child to always use a protractor without discussion"],"answer":1,"explanation":"The misconception confuses angle with arm length. Seeing an angle as an amount of turn, with arms that can be extended without changing it, builds the correct concept.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-113","question":"Asked to write ‘four hundred and five’ in numerals, a Class 3 child writes 4005. The error most clearly shows that the child:","options":["Writes numbers as they sound (400 then 5) without understanding that each digit’s value depends on its place","Cannot write the digit 5","Does not know the number name ‘four hundred’","Is careless and needs to be scolded"],"answer":0,"explanation":"Children who write ‘400’ and ‘5’ side by side are transcribing the spoken form. Place value mats and expanded forms (400 + 0 + 5) build the idea that zero holds the tens place.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-114","question":"A child works out 23 × 14 as 23 × 4 = 92 and 23 × 1 = 23, then adds to get 115. The real source of the error is that the child:","options":["Cannot multiply by 4","Does not know the table of 23","Treats the 1 in 14 as one instead of one ten, so 23 × 10 = 230 is never formed","Adds instead of multiplying"],"answer":2,"explanation":"The correct product is 92 + 230 = 322. The ‘shift’ in the algorithm stands for multiplying by ten; an area or grid method (20 × 10, 3 × 10, 20 × 4, 3 × 4) makes this visible.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-115","question":"A Class 4 child divides 728 by 7 and writes the quotient as 14. The most likely misconception and the correct quotient are:","options":["The child cannot do 7 ÷ 7; the answer is 140","The child divided by 2 instead of 7; the answer is 104","The child made a table error; the answer is 114","When the tens digit 2 cannot be divided by 7, the child moves on without recording 0 in the tens place; the answer is 104"],"answer":3,"explanation":"7 hundreds ÷ 7 = 1 hundred, 2 tens ÷ 7 = 0 tens (carry 20), 28 ones ÷ 7 = 4, so 104. Estimating first (700 ÷ 7 = 100) would show that 14 is far too small.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-116","question":"A teacher asks Class 4 children to make up their own word problems for 24 ÷ 4 and share them. The main pedagogical value of this task is that it:","options":["Reduces the teacher’s work in preparing questions","Shows whether children understand what division means in real situations, for example sharing and grouping","Is mainly a test of children’s handwriting","Helps children memorise the division table faster"],"answer":1,"explanation":"Problem posing reveals whether children can connect the symbol to meaning; it often exposes children who can calculate but cannot tell when division applies.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-117","question":"Which problem models division as grouping (measurement or quotitive division) rather than as equal sharing?","options":["12 sweets are shared equally among 3 children. How many does each child get?","A ribbon of 12 m is cut into 3 equal pieces. How long is each piece?","There are 12 sweets and each child gets 3. How many children get sweets?","12 apples are put equally into 3 baskets. How many are in each basket?"],"answer":2,"explanation":"In grouping, the size of each group is known and the number of groups is asked; in sharing, the number of groups is known and the size of each is asked. Children need experience of both.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-118","question":"Which assessment item would give a teacher the MOST diagnostic information about children’s understanding of subtraction?","options":["Ten sums of the form 64 − 28, marked right or wrong","A timed test of subtraction facts","A multiple-choice question on the subtraction rule","Solving 64 − 28 and explaining, in words or drawings, how they got the answer"],"answer":3,"explanation":"An explanation shows the strategy and reasoning behind the answer, revealing specific misconceptions; right/wrong marks show only whether the result was correct.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-119","question":"The NCF 2005 position paper on mathematics distinguishes a ‘narrow aim’ and a ‘higher aim’ of school mathematics. The higher aim is to:","options":["Develop the child’s inner resources to think and reason mathematically, pursue assumptions to their logical conclusion and handle abstraction","Teach useful numeracy for daily life, such as calculation and measurement","Prepare every child for competitive entrance examinations","Complete the syllabus with plenty of drill"],"answer":0,"explanation":"The narrow aim is useful numeracy; the higher aim is to develop mathematical thinking itself, which NCF 2005 calls the main goal (mathematisation).","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-120","question":"Children can correctly show 42 − 17 with base-ten blocks by exchanging a ten for ten ones, but they still make errors in the written column method. The teacher’s best next step is to:","options":["Stop using blocks because they are confusing the children","Let the children record each step on paper as they carry it out with the blocks, explicitly linking the exchange to the regrouping in the written method","Teach the written method separately as a set of rules","Give them more practice with the blocks only"],"answer":1,"explanation":"Concrete materials help only when connected to the symbols; recording alongside the action builds the bridge from the enactive to the symbolic form.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-121","question":"Exploring a calendar, children find that in several 3 × 3 blocks the sum of the nine dates equals 9 times the middle date. One child says, ‘If the middle is n, the dates are n − 8, n − 7, n − 6, n − 1, n, n + 1, n + 6, n + 7, n + 8, and they add up to 9n.’ This child has moved from:","options":["Rote recall to calculation","Measurement to estimation","Checking examples to a general argument showing why the pattern must always hold","Algebra back to arithmetic"],"answer":2,"explanation":"Testing cases is inductive; using a variable to show the pattern holds for every block is generalisation and justification, a key step towards algebraic reasoning.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-122","question":"A Class 3 child shades one part of a circle divided into four unequal parts and calls it ‘one-fourth’. The child has not yet understood that:","options":["Fractions can only be shown with circles","The parts must be equal for each to be a fourth of the whole","A fraction must always have 1 as its numerator","Shading must start from the top"],"answer":1,"explanation":"A fraction names one of several equal parts. Folding paper strips into equal and unequal parts and comparing helps children see this.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-123","question":"When the clock shows 3:45, a child reads it as ‘4:45’ because the hour hand is almost at 4. What does the child not yet understand?","options":["How to count in fives","That the minute hand is longer","How many minutes make an hour","That the hour hand moves gradually from one number to the next during the hour, so it is still ‘3 o’clock-something’ until it reaches 4"],"answer":3,"explanation":"Reading time needs coordinating both hands; using a geared clock to watch the hour hand travel between numbers as the minute hand goes round builds this understanding.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-124","question":"‘Ram has 5 more marbles than Shyam. Ram has 12 marbles. How many does Shyam have?’ Many children answer 17, explaining ‘more means add’. The best teaching response is to:","options":["Ask children to model the situation, for example by drawing a bar for Ram and a shorter bar for Shyam, instead of relying on key words","Give a list of key words for each operation to memorise","Tell children to always subtract in problems with two numbers","Avoid such problems because they are confusing"],"answer":0,"explanation":"The key-word strategy fails whenever the language is ‘inconsistent’ with the operation. Representing the relationship (Shyam = 12 − 5 = 7) builds real problem comprehension.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-125","question":"In mathematics education, a task is a genuine ‘problem’ for a learner (rather than an exercise) when:","options":["It contains large numbers","It is taken from the end of a textbook chapter","The learner does not immediately know a method for solving it and has to think out a way","It has been solved by the teacher on the board first"],"answer":2,"explanation":"A problem requires the learner to devise an approach; an exercise practises a method already known. The same task can be a problem for one child and an exercise for another.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-126","question":"A Class 6 student checks that 3 + 5, 7 + 9, 11 + 13, 1 + 1 and 15 + 21 are all even, and says she has ‘proved’ that the sum of two odd numbers is always even. The best teacher response is to:","options":["Accept it, since five examples are enough","Tell her the statement is false","Ask her to test fifty more examples","Appreciate the evidence, explain that examples cannot prove a statement for all numbers, and help her build a general argument (each odd number is an even number plus one, so two ‘leftover ones’ make a pair)"],"answer":3,"explanation":"Examples support a conjecture but cannot cover every case. A general argument (for example 2m + 1 + 2n + 1 = 2(m + n + 1)) shows why it must always hold, introducing children to mathematical proof.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-127","question":"A Class 5 student who is blind is learning about shapes and number operations in an inclusive class. Which resources are most suitable?","options":["Coloured charts and printed worksheets","Tactile shapes on raised boards, geoboards with rubber bands, and an abacus, with all written work read aloud","Asking a classmate to do the work for her","Exempting her from geometry, since it is visual"],"answer":1,"explanation":"Tactile materials and an abacus give access to geometry and calculation; exemption or having others do the work denies her the learning the RPwD Act aims to secure.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-128","question":"Which practice is most likely to REDUCE mathematics anxiety among children?","options":["Daily timed tests with the results read out in class","Insisting on one ‘correct’ method for every problem","Valuing different solution strategies, treating errors as part of learning, and avoiding public comparison of speed","Making slow children stand until they answer correctly"],"answer":2,"explanation":"Fear of public failure and speed pressure feed maths anxiety; an environment that values reasoning over speed and accepts multiple methods reduces it, as NCF 2005 urges.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-129","question":"Asked, ‘What is the difference between 15 and 9?’, a child says, ‘15 has a 1 and 5, and 9 has only one digit.’ The teacher should recognise that:","options":["The child lacks number knowledge and must go back to counting","The child is being deliberately cheeky","The question is too difficult for primary children","The child is using the everyday meaning of ‘difference’, so mathematical words that also have everyday meanings need to be discussed explicitly"],"answer":3,"explanation":"Words such as difference, product, table and volume have different everyday meanings. Making the mathematical meaning explicit is part of developing the language of mathematics.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-130","question":"During an EVS lesson on families, a Class 3 child says, ‘I live only with my mother and grandmother.’ Some classmates laugh. The most appropriate response of the teacher is to:","options":["Tell the class that a ‘proper’ family has a father, mother and children","Ignore the remark and continue with the textbook picture","Ask the child to sit quietly so that she is not embarrassed further","Use the moment to discuss that families differ in size and members, and invite children to share who lives in their homes without judgement"],"answer":3,"explanation":"EVS aims to help children appreciate diversity in families and lifestyles; building on the child’s experience respectfully counters stereotypes and teasing.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-131","question":"Many questions in the NCERT EVS books (‘Have you ever seen…?’, ‘What do people in your family do when…?’) have no answer printed in the chapter. The main reason is that:","options":["The answers have been left out to save space","These questions draw out children’s own experiences, so many different answers can be right and should be accepted","Children are expected to find the single correct answer from a guidebook","Teachers are expected to dictate model answers for children to memorise"],"answer":1,"explanation":"The books treat children as sources of knowledge; open questions link EVS to the child’s life and require teachers to accept varied responses rather than one ‘right’ answer.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-132","question":"In an EVS activity, children collect leaves and group them by shape, edge and texture, explaining their groups. Which NCERT indicator of EVS learning is mainly being assessed?","options":["Classification","Concern for justice and equality","Experimentation","Cooperation"],"answer":0,"explanation":"Grouping objects by observed features and explaining the basis of grouping is the indicator ‘classification’; it also draws on observation.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-133","question":"Match the EVS classroom behaviour with the NCERT learning indicator it best shows: 1. A child asks, ‘Why do some birds have long, thin beaks?’ 2. A child objects that a chapter’s story treats a girl unfairly. 3. A child tries soaking seeds in different amounts of water to see what happens. 4. A child explains in her own words why clothes dry faster on a windy day; a. Explanation b. Experimentation c. Concern for justice and equality d. Questioning","options":["1-d, 2-c, 3-b, 4-a","1-a, 2-c, 3-b, 4-d","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":0,"explanation":"Asking ‘why’ is questioning, objecting to unfair treatment shows concern for justice and equality, trying out conditions is experimentation, and accounting for a phenomenon in one’s words is explanation.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-134","question":"A teacher holds up a cricket ball and a tennis ball and asks, ‘If I drop them together from this height, which will land first? Write down your guess and why.’ She then drops them, and the class discusses why the result differed from many predictions. This strategy is called:","options":["Concept mapping","Brainstorming","Predict–Observe–Explain","Programmed instruction"],"answer":2,"explanation":"POE makes children commit to a prediction, which brings out their ideas (heavier falls faster), then uses observation and discussion to challenge and reconstruct them.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-135","question":"A Class 7 student explains that it is winter in December ‘because the earth is then farthest from the sun’. Which piece of evidence would best challenge this idea?","options":["The earth moves in an orbit around the sun","When it is winter in India, it is summer in Australia, though both are at almost the same distance from the sun","The sun appears smaller in winter","Days are shorter in winter"],"answer":1,"explanation":"If distance caused seasons, both hemispheres would have the same season at once. Opposite seasons in the two hemispheres point to the tilt of the earth’s axis as the cause.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-136","question":"A Class 4 child says, ‘A bus is living because it moves, but a tree is not living because it does not move.’ Which teaching approach best addresses this idea?","options":["Make the child memorise the definition of a living thing","Tell the child that only animals are living","Show a video of a moving bus","Help children list and test several features, such as growth, need for food and water, reproduction and response, and apply them to the tree and the bus"],"answer":3,"explanation":"The child is using one feature (movement) as the test of life. Considering several characteristics together lets children see why a tree is living and a bus is not.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-137","question":"To find out whether seeds need water to sprout, a child puts seeds on wet cotton in one bowl and on dry sand in another. The main flaw in this test is that:","options":["Two factors, water and the material, have been changed at once, so the result cannot be linked to water alone","Seeds should be planted in a pot, not a bowl","Only one bowl should have been used","The child should have used a microscope"],"answer":0,"explanation":"A fair test changes only the factor under study and keeps everything else the same; here cotton should be used in both bowls, one wet and one dry.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-138","question":"Class 8 students decide on their own question (‘Does the colour of a cloth affect how fast it dries?’), plan their own method, collect data and present conclusions, with the teacher only facilitating. This is best described as:","options":["Confirmation inquiry","Structured inquiry","Open inquiry","Teacher demonstration"],"answer":2,"explanation":"In open inquiry students frame the question and design the investigation themselves. In structured inquiry the teacher gives the question and procedure, and in confirmation inquiry students verify a known result.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-139","question":"The NCF 2005 position paper on science lists criteria a good science curriculum must meet. Including the story of how scientific ideas changed over time, such as the shift from an earth-centred to a sun-centred view, mainly serves:","options":["Cognitive validity","Ethical validity","Environmental validity","Historical validity"],"answer":3,"explanation":"Historical validity means the curriculum shows how science developed and changed, showing it as a social enterprise. The other criteria are cognitive, content, process, environmental and ethical validity.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-140","question":"Under the NCF 2005 science criteria, a curriculum has ‘process validity’ when it:","options":["Is suited to the age and cognitive level of learners","Engages learners in acquiring the methods and processes that generate and validate scientific knowledge","Presents scientifically correct and significant content","Promotes values of honesty, objectivity and concern for life"],"answer":1,"explanation":"Process validity concerns learning how scientific knowledge is generated, through observation, experiment and reasoning. The other options describe cognitive, content and ethical validity.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-141","question":"Class 5 children interview their grandparents about where the family got drinking water fifty years ago and compare it with today. The main learning purpose of this activity in EVS is to help children:","options":["Understand change over time and connect it with people’s lives and the environment","Improve their handwriting through note-taking","Memorise the names of water sources","Learn that old practices were always better"],"answer":0,"explanation":"Oral history surveys link the present to the past and show how environment and society shape each other, an integrated EVS aim; they also develop questioning and recording skills.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-142","question":"Children draw a map of their route from home to school, marking landmarks such as a temple, a shop and a pond. This activity mainly helps them to:","options":["Learn the scale and projection of standard maps","Memorise the names of shops","Develop a sense of space and direction, the basis of later map reading","Improve their drawing as an art activity"],"answer":2,"explanation":"Drawing familiar routes builds spatial understanding, perspective and the use of symbols, the foundation of mapping skills developed later in EVS.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-143","question":"A teacher fills her science periods with activities: children float objects, mix colours and grow seeds, but she moves straight on to the next activity without any discussion. What is most clearly missing?","options":["More activities, so that children are kept busy","A written test after every activity","Strict silence during the activities","Discussion and reflection that help children make sense of what they observed and link it to ideas: the activities are ‘hands-on’ but not ‘minds-on’"],"answer":3,"explanation":"Activities lead to learning only when children are helped to think about what happened, explain it and connect it to concepts; activity alone does not build understanding.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-144","question":"In a school without a science laboratory, a teacher uses plastic bottles, straws, balloons and old cells to teach ideas about air pressure and electricity. This practice is best described as:","options":["Poor teaching, because real apparatus is always needed","Improvisation with low-cost local materials, which NCF 2005 encourages","A waste of class time","Suitable only for children who cannot afford books"],"answer":1,"explanation":"Low-cost, improvised materials make hands-on science possible everywhere and help children see science in everyday objects.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-145","question":"To explain an electric circuit, a teacher compares electric current to water flowing in pipes. Which follow-up best uses this analogy responsibly?","options":["Discussing where the analogy works and where it breaks down, for example that a cut wire does not ‘leak’ electricity like a cut pipe leaks water","Avoiding analogies altogether, since they always cause misconceptions","Telling children that electricity is a kind of water","Using the analogy only in tests"],"answer":0,"explanation":"Analogies help children grasp abstract ideas, but learners can transfer irrelevant features; making the limits explicit prevents new misconceptions.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-146","question":"A teacher shows a cartoon in which three children give different views about why a snowman wrapped in a coat will melt faster, slower or at the same rate, and asks the class whom they agree with and why. The main purpose of such a concept cartoon is to:","options":["Entertain children before the real lesson begins","Test whether children can read","Draw out children’s existing ideas and get them to argue and test them","Give the correct answer in an attractive form"],"answer":2,"explanation":"Concept cartoons present competing ideas, including common misconceptions, to provoke discussion and investigation (here, a coat insulates and slows melting).","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-147","question":"An EVS discussion asks who in the neighbourhood cleans drains and collects garbage, how they are treated, and how the children would feel doing that work. The main aim of such a discussion is to:","options":["Teach children the steps of cleaning a drain","Discourage children from keeping their surroundings clean","Show that such work belongs to particular communities","Sensitise children to the dignity of all labour and to social inequities linked to work"],"answer":3,"explanation":"EVS includes the social environment; examining who does what work and how they are treated promotes empathy, equality and respect for labour.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-148","question":"A Class 3 child who cannot yet write well draws a detailed picture of how her family stores water at home and explains it orally. As an EVS assessment, the teacher should:","options":["Give no marks, because nothing has been written","Accept the drawing and oral explanation as valid evidence of her learning","Ask her to copy a written answer from the board instead","Mark her down for not using the textbook answer"],"answer":1,"explanation":"Assessment in EVS should allow varied forms of expression; drawing and speaking are valid ways to show observation and understanding, especially in early grades.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-149","question":"Class 6 students can recite that ‘photosynthesis is the process by which green plants make food using sunlight’, but cannot explain why a plant kept in a dark cupboard for a week has become pale and weak. This shows that their learning is mainly:","options":["Rote, without conceptual understanding that can be applied to a new situation","Conceptual, because they know the definition","Experiential, since they have seen plants","Complete, as the definition is correct"],"answer":0,"explanation":"Applying an idea to explain a new situation is a test of understanding; reproducing a definition shows only memorisation.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-150","question":"Which behaviour of a student best shows a scientific attitude?","options":["Changing her readings so that they match the textbook value","Accepting a claim because it was made by an elder","Recording a surprising result honestly and repeating the experiment to check it","Refusing to consider a classmate’s explanation that differs from hers"],"answer":2,"explanation":"Honesty in recording data, scepticism and willingness to check results are the core of scientific attitude; fudging data or accepting authority uncritically are not.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-151","question":"Asked to group pictures of 12 animals, one group sorts by ‘lives on land / in water’, another by ‘has legs / no legs’ and a third by ‘eats plants / eats animals’. The teacher should:","options":["Accept only the textbook grouping and mark the others wrong","Choose the ‘best’ group and ask others to copy it","Tell children that classification can only be done by scientists","Accept all groupings that follow a clear, consistently applied criterion, and discuss how different purposes lead to different classifications"],"answer":3,"explanation":"Classification depends on the criterion chosen; what matters is that it is clearly stated and applied consistently. Discussing different schemes deepens understanding.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-152","question":"In an EVS lesson on food, a teacher encourages children to use the local names of grains, vegetables and dishes eaten at home. The main reason is that this:","options":["Connects classroom learning with children’s home knowledge and language, making it meaningful","Avoids the need for any standard names","Saves time in teaching","Shows which children come from rural families"],"answer":0,"explanation":"Using children’s own words and experiences validates home knowledge and helps them link new learning to what they already know.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-153","question":"Many Class 7 students believe that electric current ‘gets used up’ in a bulb, so less current returns to the cell. Which activity best challenges this idea?","options":["Telling them that energy is conserved","Measuring the current with an ammeter before and after the bulb in a simple circuit, or noting that two identical bulbs in series glow equally","Making them memorise the definition of current","Showing that a bulb gets hot"],"answer":1,"explanation":"In a series circuit the current is the same everywhere; equal ammeter readings on both sides of the bulb directly contradict the ‘used up’ model. Energy, not charge, is transferred in the bulb.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-154","question":"A teacher holds an open-book test in EVS. Which kind of question suits it best?","options":["‘List the six themes of EVS.’","‘Write the definition of a food chain.’","‘Name three sources of water.’","‘The pond near your school has dried up this summer. Using your book and your own observations, explain two possible reasons and suggest what the village could do.’"],"answer":3,"explanation":"Open-book tests are meant to assess application, analysis and reasoning; recall questions would only reward copying from the book.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-155","question":"A teacher wants to show a reaction that involves heating a strong acid. The most suitable method is:","options":["A teacher demonstration with proper safety, followed by discussion, because the activity is hazardous for children to perform","Letting each child do it alone to build confidence","Skipping the topic altogether","Only reading about it in the textbook"],"answer":0,"explanation":"Demonstration is appropriate when materials are dangerous, expensive or scarce; children can still predict, observe and explain, keeping it inquiry-oriented.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-156","question":"Which question in an EVS lesson on water best promotes critical thinking about the social environment?","options":["‘What colour is water?’","‘Name two rivers of India.’","‘In your area, who walks the farthest to fetch water, and why might that be so?’","‘How many glasses of water do you drink a day?’"],"answer":2,"explanation":"This question asks children to notice and reason about unequal access to resources (by gender, place or class), linking science and social issues as EVS intends.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-157","question":"How many of the following are consistent with the NCF 2005 view of science teaching at the upper primary stage? I. Learning science through familiar experiences and simple experiments. II. Treating science as a fixed set of facts to be memorised. III. Encouraging children to ask questions and test their own ideas. IV. Linking science with environmental and health concerns.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV match NCF 2005, which sees science as a process of inquiry. Viewing it as a fixed body of facts for memorisation is what it argues against.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-158","question":"Which of the following is the most suitable way to begin a Class 4 EVS lesson on ‘Our Food’?","options":["Dictating notes on carbohydrates, proteins and fats","Asking children what they ate yesterday, how it was cooked and where the ingredients came from","Giving a test on food nutrients","Writing the chapter summary on the board"],"answer":1,"explanation":"Starting from children’s own experience (their meals) makes the topic meaningful and lets the teacher build on prior knowledge, as EVS pedagogy recommends.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-159","question":"After reading a story, a teacher writes five sentences from it on the board (‘The fox jumped…’, ‘The crow dropped…’) and asks children what they notice about the action words and when the events happened. The children work out how the past tense is formed. This way of teaching grammar is:","options":["Deductive, because the rule comes first","Inductive, in context, because learners discover the rule from examples","Grammar-translation, because sentences are compared with the mother tongue","Audio-lingual, because it relies on pattern drills"],"answer":1,"explanation":"In the inductive approach, learners observe examples in meaningful context and infer the rule, which leads to better understanding than memorising a rule first.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-160","question":"A learner of English regularly writes ‘He go to school daily’, but once, while hurrying, wrote ‘They was late’ although she normally writes ‘They were’. In S. P. Corder’s terms:","options":["Both are mistakes, since she knows English","Both are errors, since both are incorrect","The first is a mistake and the second an error","The first is an error (a systematic gap in her developing knowledge) and the second a mistake (a slip in performance)"],"answer":3,"explanation":"Corder distinguished systematic errors, which reveal the learner’s current rule system, from occasional mistakes, which she can self-correct. Errors are useful evidence of what to teach next.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-161","question":"A Class 6 learner of English consistently says ‘He no like mango’ and ‘She no coming today’. Language teachers would describe this as:","options":["A sign of the learner’s developing interlanguage, a rule-governed system between the first language and the target language","Proof that the learner cannot learn English","Deliberate carelessness that should be punished","A speech disorder needing therapy"],"answer":0,"explanation":"Selinker’s interlanguage is the learner’s own evolving grammar; using ‘no’ before the verb for all negatives is a normal stage that changes with rich input and feedback.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-162","question":"A child whose home language does not allow words to begin with ‘sk’ says ‘iskool’ for ‘school’. The best teacher response is to:","options":["Correct the child sharply in front of the class every time","Recognise it as normal influence of the first language, model the word naturally, and give playful practice without embarrassing the child","Ask the child to stop speaking English until the pronunciation is perfect","Ignore spoken English and focus only on writing"],"answer":1,"explanation":"Transfer of first-language sound patterns is natural; plenty of input, modelling and low-anxiety practice help, while public correction raises the affective filter.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-163","question":"A four-year-old turns the pages of a picture book and ‘reads’ the story aloud from the pictures, though she cannot yet decode the words. This behaviour should be seen as:","options":["Cheating, because she is not reading the words","A sign of a reading disability","Emergent literacy, to be encouraged, since she understands that books carry stories and how they are handled","Proof that she has memorised the book and needs no further help"],"answer":2,"explanation":"Pretend reading shows growing concepts about print, story structure and book handling; the emergent literacy view treats such behaviour as real progress towards reading.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-164","question":"A Class 1 child writes, ‘I wnt to skool on my sikl.’ From the perspective of early writing development, the teacher should recognise that:","options":["The child must be stopped from writing until spelling is correct","The child is careless and needs to copy each word five times","The spellings show that the child has not learnt any letters","The child is using sound–letter knowledge to write independently; such invented spelling is a normal stage that should be valued while correct forms are gradually modelled"],"answer":3,"explanation":"Invented spellings like ‘skool’ and ‘sikl’ show the child hearing sounds and mapping them to letters. Encouraging writing for meaning, with gentle modelling, builds both fluency and accuracy.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-165","question":"Before reading a chapter on bees, students fill in what they already know and what they want to know, and after reading they note what they have learnt. This reading strategy is:","options":["SQ3R","The KWL chart","The cloze procedure","Skimming"],"answer":1,"explanation":"KWL (Know, Want to know, Learnt) activates prior knowledge, sets a purpose for reading and supports reflection on learning.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-166","question":"In a weekly library period, children choose storybooks they like and read many of them for pleasure, without answering questions afterwards. This is an example of:","options":["Extensive reading","Intensive reading","Scanning","Choral reading"],"answer":0,"explanation":"Extensive reading means reading a lot of self-chosen material for enjoyment and general understanding; it builds fluency, vocabulary and the reading habit. Intensive reading studies a short text closely.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-167","question":"Which is the most suitable way to teach a poem to Class 5 children?","options":["Explaining the meaning line by line and asking children to memorise the explanation","Asking children to write the meanings of difficult words before they hear the poem","Testing them on the poet’s biography","Reading it aloud with expression, letting children enjoy its rhythm and images, and inviting their responses and feelings before any close discussion"],"answer":3,"explanation":"Poetry is first to be enjoyed and responded to; line-by-line paraphrase and memorised meanings kill the pleasure and personal response that literature aims to develop.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-168","question":"A teacher gives each essay a single overall grade based on her general impression of its quality, rather than separate marks for content, organisation, vocabulary and grammar. Which statement is correct?","options":["She is using analytic scoring, which gives detailed diagnostic feedback","She is using holistic scoring, which is quick but gives less diagnostic information than analytic scoring","She is using a checklist","She is using norm-referenced scoring"],"answer":1,"explanation":"Holistic scoring rates the whole piece at once; analytic scoring rates separate components and so shows learners exactly where to improve.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-169","question":"Students work in pairs: one has a picture of a room and the other a slightly different picture. Without showing their pictures, they talk to find the differences. This kind of task is called:","options":["A substitution drill","Choral repetition","An information-gap activity","Dictation"],"answer":2,"explanation":"In an information-gap activity each learner has information the other needs, so they must communicate for a real purpose, a core technique of the communicative approach.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-170","question":"A teacher of young learners says, ‘Stand up! Touch your nose! Hop three times! Sit down!’ and children respond with actions, without being required to speak yet. This method is:","options":["The grammar-translation method","The silent way","The direct method using reading aloud","Total Physical Response (TPR)"],"answer":3,"explanation":"Asher’s TPR links language with physical action, lets learners first show understanding through movement, and keeps anxiety low before speaking is expected.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-171","question":"A Class 3 child reads very slowly, word by word with a finger under each word, though he decodes accurately. Which strategy is most likely to improve his reading fluency?","options":["Repeated reading of familiar texts, along with echo or paired reading with a fluent reader","More phonics worksheets on letter sounds","Asking him to read silently only","Giving him longer and harder texts so that he is challenged"],"answer":0,"explanation":"He already decodes; what he lacks is automaticity. Re-reading familiar texts and hearing fluent models build speed, phrasing and expression.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-172","question":"While reading, a child meets the word ‘parched’ in ‘After weeks without rain, the parched fields cracked open.’ Which strategy should the teacher encourage first?","options":["Stop reading and look up the dictionary at once","Skip the word since it is not important","Use clues in the sentence, such as ‘weeks without rain’ and ‘cracked’, to guess the meaning, and then check","Ask the teacher for the meaning of every new word"],"answer":2,"explanation":"Guessing meaning from context keeps reading fluent and builds independent word learning; the dictionary can confirm the guess later.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-173","question":"A three-year-old points at a new object and keeps asking, ‘What’s that? Why?’ In Michael Halliday’s account of children’s language functions, this use of language is:","options":["Instrumental","Regulatory","Imaginative","Heuristic"],"answer":3,"explanation":"Halliday’s heuristic function is using language to explore and learn about the world. Instrumental is getting things (‘I want…’), regulatory is controlling others, and imaginative is creating pretend worlds.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-174","question":"A Class 8 student writes a leave application to the principal beginning, ‘Hey Sir! Can’t come tomorrow, got stuff to do.’ The student mainly needs help with:","options":["Spelling","Register: choosing language suited to the purpose, audience and situation","Handwriting","Grammar of the past tense"],"answer":1,"explanation":"The sentence is grammatical but too informal for a formal letter. Comparing texts for different audiences builds awareness of register.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-175","question":"A Class 5 teacher has children write their own stories, revise them with peer feedback and publish them in a class magazine read by other classes and parents. The main pedagogical value of publishing is that it:","options":["Gives children a real audience and purpose, which motivates careful writing and revision","Saves the teacher from correcting the stories","Helps children memorise the stories","Allows the teacher to rank children by their writing"],"answer":0,"explanation":"Writing for real readers gives purpose, raises motivation and makes revision meaningful, a key idea of the process and whole-language approaches.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-176","question":"Which item from a Class 4 language test best assesses creative and divergent thinking?","options":["‘Who was the king in the story?’","‘Write the meaning of the word “brave”.’","‘Rewrite the ending of the story so that the king learns his lesson in a different way.’","‘Fill in the blank with the correct form of the verb.’"],"answer":2,"explanation":"Rewriting the ending is open-ended, allows many acceptable answers and requires imagination; the others check recall or a single correct form.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-177","question":"Which task integrates listening, speaking, reading and writing most fully?","options":["Copying a paragraph from the board","Children listen to a radio weather report, discuss it in groups, read a newspaper forecast, and write a forecast for their own town","Reading a lesson silently and answering in one word","Reciting a poem from memory"],"answer":1,"explanation":"Language skills develop best together through meaningful tasks; this sequence uses all four in a connected way, unlike tasks that isolate one skill.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-178","question":"Assertion (A): Grammar should be taught through rules and exercises in isolation before children start using the language for communication. Reason (R): Knowing grammar rules is the main way children acquire the ability to speak a language.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are false"],"answer":3,"explanation":"Children acquire language mainly through meaningful use and rich input; grammar is better learnt in context alongside use, not as a precondition for it.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-179","question":"A Class 2 child reads the sentence ‘The boy ran to his house’ aloud as ‘The boy ran to his home’. In miscue analysis this miscue suggests that the child:","options":["Cannot read and needs to start again with the alphabet","Is careless and should be stopped and corrected at once","Is using meaning (semantic) cues and understands the sentence, though attention to the print can be sharpened","Has a visual problem"],"answer":2,"explanation":"Goodman’s miscue analysis treats reading errors as windows into the strategies a reader uses. A substitution that keeps the meaning shows the child is reading for sense.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-180","question":"Which classroom plan best reflects a balanced approach to early literacy?","options":["Phonics drills only, with no stories until the child can decode","Stories only, with no attention to letters and sounds","Daily read-alouds and shared reading of meaningful texts along with systematic work on sounds and letters, and opportunities for children to write","Copying letters and words from the board for most of the period"],"answer":2,"explanation":"Balanced literacy combines meaning-centred reading and writing with explicit teaching of the sound–letter system, rather than either alone.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-181","question":"For a student with a visual impairment in a language class, the most suitable support is:","options":["Exempting her from reading and writing","Audio books, Braille or large-print texts, and reading aloud whatever is written on the board","Asking a friend to do her homework","Seating her at the back of the class"],"answer":1,"explanation":"Accessible formats and oral support let her take full part in reading and writing; exemption or dependence on others denies her learning.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-182","question":"Regular storytelling in the early grades mainly helps children to:","options":["Prepare for written examinations","Learn grammar rules","Improve their handwriting","Develop listening, vocabulary, imagination and a sense of how stories are structured"],"answer":3,"explanation":"Stories expose children to rich language in meaningful context and build listening comprehension, vocabulary, prediction and narrative sense, the base for reading.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-183","question":"A teacher keeps a folder for each child with dated samples of writing from the year, a reading log, an audio recording of the child reading, and the child’s comments on her own progress. This tool is a:","options":["Portfolio","Cumulative record","Rating scale","Question bank"],"answer":0,"explanation":"A language portfolio is a purposeful collection showing growth over time with the learner’s reflection; it supports continuous, comprehensive assessment.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-184","question":"Which question about a story checks evaluative (critical) comprehension?","options":["‘Where did the farmer go in the morning?’","‘Why do you think the farmer did not tell anyone about the treasure?’","‘How many sons did the farmer have?’","‘Do you think the farmer was fair to his sons? Give reasons.’"],"answer":3,"explanation":"Evaluative questions ask readers to judge ideas or actions using their own values and reasoning. ‘Why do you think…’ asks for an inference, and the others check literal recall.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-185","question":"According to NCF 2005, the main aim of teaching a second language such as English in the early years is that children should:","options":["Acquire basic proficiency for natural communication and build on it, using the home language as a resource","Learn grammar rules thoroughly before using the language","Read only prescribed textbooks","Translate texts word by word into the mother tongue"],"answer":0,"explanation":"NCF 2005 stresses acquiring the second language through rich, comprehensible input and meaningful use, with multilingualism as a resource, rather than through grammar and translation.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-186","question":"A Class 7 teacher asks students to record a conversation in the market, transcribe it, and compare it with a dialogue in their textbook. The main learning outcome is awareness of:","options":["The difference between spoken and written language, including features such as fillers, incomplete sentences and turn-taking","The spelling of difficult words","The history of the market","Handwriting speed"],"answer":0,"explanation":"Analysing real speech helps learners notice how spoken language differs from written dialogue, building language awareness and sensitivity to how language is used.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-187","question":"Which practice in a language class is LEAST consistent with treating errors as part of learning?","options":["Noting common errors and addressing them later through focused practice","Recasting a child’s incorrect sentence correctly in the teacher’s reply","Interrupting a child in mid-sentence to correct every error while she is telling a story","Encouraging peers to give each other feedback on drafts"],"answer":2,"explanation":"Constant interruption focuses on form over meaning, raises anxiety and discourages speaking; the other practices give feedback without blocking communication.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-188","question":"A Class 7 student simplifies 2a + 3b as 5ab. Which teacher response is most likely to help her see the error for herself?","options":["Tell her that unlike terms can never be added and ask her to memorise this","Give her ten more sums of the same kind","Ask her to put a = 2 and b = 3 into both expressions and compare the values (13 and 30)","Explain that ‘ab’ means a times b"],"answer":2,"explanation":"Substituting numbers shows that the two expressions are not equal, which creates cognitive conflict and builds the idea that letters stand for numbers; a rule alone does not.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-189","question":"Asked to write an expression for ‘the cost of 3 pens and 2 books’, a student writes ‘3p + 2b’ and explains, ‘p means pens and b means books.’ The teacher’s main concern should be that the student:","options":["Has written the wrong expression","Sees letters as labels for objects rather than as numbers (here, the price of one pen and of one book)","Does not know multiplication","Should have used x and y"],"answer":1,"explanation":"The expression is right, but the ‘letter as object’ (fruit-salad) view causes later errors, such as reading 3p as ‘3 pens’. The teacher should stress that p stands for the price of one pen.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-190","question":"A Class 6 student says −5 is greater than −2 ‘because 5 is greater than 2’. Which context best helps correct this idea?","options":["Temperatures on a thermometer: −5 °C is colder than −2 °C, so it lies lower on the scale","Telling the student that the rule for negatives is the opposite","Counting objects in groups of 5 and 2","Adding −5 and −2"],"answer":0,"explanation":"A vertical number line such as a thermometer shows that numbers further below zero are smaller, giving meaning to the order of negative integers.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-191","question":"Most students in a class claim that if a price is increased by 20% and then decreased by 20%, it returns to the original price. The best teaching move is to:","options":["Tell them they are wrong and give the formula","Skip the problem as too advanced","Ask them to memorise that successive changes are not additive","Ask them to try it with a price of ₹100 (₹100 → ₹120 → ₹96) and explain why the second 20% is of a different amount"],"answer":3,"explanation":"Working with a concrete value reveals the result and shows why: the 20% decrease is taken on ₹120, not ₹100. Students then construct the idea of a changing base themselves.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-192","question":"A recipe for 4 people needs 6 cups of rice. Asked how much is needed for 6 people, a child says 8 cups ‘because 2 more people means 2 more cups’. The correct amount and the child’s difficulty are:","options":["9 cups; the child is using additive rather than multiplicative (proportional) reasoning","8 cups; the child is right","10 cups; the child has made a counting error","12 cups; the child should double the amount"],"answer":0,"explanation":"Each person needs 6 ÷ 4 = 1.5 cups, so 6 people need 9 cups. Adding a fixed difference instead of keeping the ratio is the most common error in proportional reasoning.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-193","question":"To help Class 4 children understand symmetry, the most suitable activity is:","options":["Writing the definition of a line of symmetry five times","Folding paper cut-outs and ink-blot patterns along a line to see whether the two halves match exactly","Reading the chapter on symmetry silently","Measuring the angles of a square"],"answer":1,"explanation":"Folding and matching halves gives a direct, hands-on experience of reflection symmetry that children can then look for in letters, leaves and rangoli.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-194","question":"A child finds the area of a 4 cm by 3 cm rectangle and writes ‘12 cm’. The teacher’s best response is to:","options":["Deduct a mark and move on","Explain that the formula is length × breadth","Let the child cover the rectangle with 1 cm × 1 cm squares and count them, so that she sees area is counted in square units","Ask her to measure the sides again"],"answer":2,"explanation":"The number is right but the unit shows she does not yet see area as the number of unit squares covering a surface; tiling builds this meaning of cm².","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-195","question":"A teacher studies symmetry and patterns through the rangoli, kolam and weaving designs that children’s families make at home. This approach is best described as:","options":["Rote learning of geometric terms","Recreational mathematics with no link to the syllabus","Avoiding formal geometry","Drawing on ethnomathematics, connecting school mathematics with the mathematics in children’s cultural practices"],"answer":3,"explanation":"Ethnomathematics recognises mathematical ideas in everyday cultural practices; using them links school maths to children’s lives, as NCF 2005 recommends.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-196","question":"A shop offers ‘Buy 2, get 1 free’ while another offers ‘30% off’ on the same item. Which question built on this situation best assesses application and reasoning in Class 7?","options":["‘Which offer gives the bigger discount on 3 items? Show your reasoning.’","‘Define percentage.’","‘Write 30% as a fraction.’","‘What is 30% of 100?’"],"answer":0,"explanation":"Comparing offers needs students to see that ‘buy 2, get 1 free’ is a 1/3 (about 33.3%) discount on 3 items, better than 30%; the other items test recall or routine calculation.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-197","question":"At the end of a maths lesson, each child writes on a slip one thing she learnt and one question she still has, and hands it to the teacher on the way out. The teacher uses the slips to plan the next lesson. This practice is:","options":["A summative assessment","A norm-referenced test","An exit slip used for formative assessment","A diagnostic test of intelligence"],"answer":2,"explanation":"Exit slips give quick evidence of what children understood and where they are stuck, which the teacher uses to adjust teaching, the defining use of formative assessment.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-198","question":"In a Class 5 class of mixed abilities, which task is best suited to engage all learners in mathematics?","options":["A worksheet of 30 identical sums","A low-floor, high-ceiling task such as ‘How many different rectangles can you make with 24 square tiles? Which has the longest perimeter?’","Separate worksheets for ‘weak’ and ‘bright’ students with no shared work","A speed test of tables"],"answer":1,"explanation":"Low-floor, high-ceiling tasks let every child start easily and allow able learners to go much deeper (all factor pairs, patterns in perimeter), supporting inclusion without labelling.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-199","question":"Many Class 7 students believe that ‘plants breathe in carbon dioxide in the day and respire only at night’. Which statement should the teacher help them reach?","options":["Plants photosynthesise only at night","Plants do not respire at all","The students are right","Plants respire all the time, day and night; in bright light, photosynthesis is faster than respiration, so there is a net uptake of carbon dioxide"],"answer":3,"explanation":"Respiration goes on continuously in all living cells; in daylight it is masked by faster photosynthesis. The misconception confuses net gas exchange with the processes themselves.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-200","question":"A Class 6 student explains that we see a book because ‘light goes out from our eyes to the book’. Which activity best challenges this idea?","options":["Reading the definition of reflection","Telling the student that the idea is ancient and wrong","Asking the student to look at objects in a completely dark room, then discussing why nothing can be seen even with eyes open","Drawing the eye and labelling its parts"],"answer":2,"explanation":"If eyes sent out light, we could see in total darkness. The experience leads to the idea that light from a source is reflected by objects into our eyes.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-201","question":"Which school practice best develops children’s concern for the environment, as intended in EVS?","options":["Children take part in a school garden, segregate waste and track the school’s water use, and discuss what they find","Children copy a list of ‘do’s and don’ts’ for the environment","Children write an essay on pollution from a guidebook","Children memorise the names of environmental laws"],"answer":0,"explanation":"Attitudes develop through participation and reflection on real action; copying rules or memorising information rarely changes behaviour.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-202","question":"Class 5 children prepare a puppet show to explain the water cycle, writing the dialogue and making the puppets themselves. Under NEP 2020, this is an example of:","options":["Rote learning through repetition","Art-integrated learning, in which an art form is used to learn a concept","Co-scholastic activity unrelated to EVS","Summative assessment"],"answer":1,"explanation":"NEP 2020 recommends art-integrated education, using the arts as a medium for learning concepts across subjects, which also builds creativity and communication.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-203","question":"Which practice best reflects the play-based and toy-based pedagogy that NEP 2020 recommends for the foundational stage?","options":["Daily worksheets of letter and number writing","Long lectures followed by question-answer","Children learning counting, sorting and patterns with local toys, games and puzzles, with the teacher guiding talk about what they do","Homework with copying of textbook pages"],"answer":2,"explanation":"For ages 3–8 NEP 2020 favours flexible, play-, toy- and activity-based learning in which concepts grow through hands-on exploration and talk.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-204","question":"Why does NCF 2005 stress oral language development in the early grades before and alongside reading and writing?","options":["Because reading and writing should not be taught before Class 3","Because oral work keeps children quiet","Because oral language is easier to assess","Because a rich spoken vocabulary and listening comprehension give children the base on which meaning-making in reading and writing is built"],"answer":3,"explanation":"Children understand in print what they already understand in speech; talk, stories and discussion build the vocabulary and comprehension that literacy depends on.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-205","question":"A Class 7 teacher regularly reads aloud chapters from a novel that is somewhat above her students’ independent reading level. The main purpose of this practice is to:","options":["Expose students to rich language and fluent, expressive reading, and motivate them to read on their own","Test their spelling","Replace the need for students to read independently","Fill time at the end of the day"],"answer":0,"explanation":"Read-alouds model fluency and expression and give access to vocabulary and ideas beyond what children can yet read alone, building interest in reading.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-206","question":"A Class 3 child asks, ‘Why does the moon change its shape?’ The teacher is not sure of the answer. The most appropriate response is:","options":["‘That is not in our syllabus.’","‘You will learn it in higher classes.’","‘It is God’s wish.’","‘Good question! I am not sure. Let us watch the moon for a few nights, draw its shape each night, and find out together.’"],"answer":3,"explanation":"Valuing questions, admitting uncertainty and investigating together models a scientific attitude and encourages children’s curiosity.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-207","question":"Class 4 children count and record the kinds of trees around the school in a table and then make a simple bar graph. Which statement best describes the pedagogy?","options":["It is purely an EVS activity unrelated to mathematics","It integrates EVS and mathematics through real data collection and representation","It is mainly a handwriting exercise","It should be done only after children learn graphs formally"],"answer":1,"explanation":"Collecting real data about their environment and representing it links EVS content with data handling, giving meaning to both.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-208","question":"During a Class 8 practical on preparing a slide of onion peel, which tool would best assess students’ practical skills?","options":["A multiple-choice test on the parts of a cell","An essay on the history of the microscope","An observation checklist used while students work (handling the peel, staining, placing the coverslip, focusing)","Asking students to copy the diagram from the book"],"answer":2,"explanation":"Practical skills are best judged as they are performed; a checklist of key steps makes such observation systematic. Written tests check knowledge about the practical, not the skill.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-209","question":"When asked to draw a scientist, most children in a class draw an old man in a white coat. The teacher’s most suitable follow-up is to:","options":["Accept it, since most scientists are men","Ignore the drawings, as they are not part of the syllabus","Ask the girls to draw a woman scientist instead","Share stories of scientists of different genders and backgrounds, including women scientists and people who do science in everyday work such as farming, and discuss who can be a scientist"],"answer":3,"explanation":"‘Draw-a-scientist’ reveals stereotypes; showing diverse role models helps all children, especially girls, see science as something they can do.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-210","question":"Class 5 students who read stories easily struggle with an EVS text explaining how the monsoon causes floods. The most useful support is to:","options":["Teach the structure of informational texts, such as cause–effect, using a graphic organiser to map causes and effects","Tell them to read the text three more times","Replace the text with a story","Ask them to memorise the paragraph"],"answer":0,"explanation":"Expository texts are organised differently from stories; explicitly teaching text structures with graphic organisers improves comprehension of informational writing.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-211","question":"A Class 2 teacher shows ‘5 − 3’ with five beads, removing three, and later a child is puzzled by ‘Raju has 5 marbles and Sita has 3. How many more does Raju have?’ The teacher should realise that:","options":["The child cannot subtract and needs more drill","Subtraction has several meanings, such as taking away and comparing, and children need experience of each, not only take-away","The comparison problem is too hard for Class 2 and should be removed","Beads should never be used for subtraction"],"answer":1,"explanation":"Take-away, comparison (difference) and missing-addend situations all use subtraction; children who meet only take-away often cannot recognise the others.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-212","question":"Which of these is the strongest reason for using a number line when teaching addition of fractions such as 1/4 + 1/2?","options":["It avoids the need for a common denominator","It is easier to draw than circles","It shows fractions as numbers with a position and size, so children can see that 1/4 + 1/2 lands at 3/4 and judge whether an answer like 2/6 is sensible","It is required by the textbook"],"answer":2,"explanation":"Area models present fractions as parts of shapes; the number line shows them as numbers on a continuum, supporting estimation and reasoning about the size of sums.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-213","question":"How many of the following match the NCF 2005 recommendations for assessment in mathematics? I. Assess the processes children use, not only the final answer. II. Use mainly speed tests of procedures. III. Include tasks that ask children to explain and justify. IV. Use assessment to understand children’s thinking and plan teaching.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are recommended. NCF 2005 criticises assessment that rewards only speed and memorised procedures.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-214","question":"Assertion (A): In the primary classes, children should be allowed to solve word problems using drawings and their own methods before formal symbols are required. Reason (R): Representing a situation in their own way helps children understand the problem and connect it later to standard notation.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Children’s own representations (drawings, objects, informal notation) build understanding of the structure of a problem, which then gives meaning to formal symbols.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-215","question":"A Class 8 science teacher wants students to understand how a hypothesis differs from a guess. Which task serves this best?","options":["Writing the definition of a hypothesis","Reading about famous inventions","Forming a testable statement such as ‘If the amount of sunlight is increased, the plant will grow taller’, and designing a fair test for it","Memorising the steps of the scientific method"],"answer":2,"explanation":"A hypothesis is a testable, reasoned prediction about a relationship between variables; framing one and planning how to test it shows the difference from a mere guess.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-216","question":"Which of the following is the best example of a ‘higher-order’ EVS question for Class 5 on the topic of animals?","options":["‘Name three animals that live in water.’","‘Which animal is called the ship of the desert?’","‘How many legs does an insect have?’","‘If all the frogs in a pond disappeared, what might happen to the insects and snakes there? Why?’"],"answer":3,"explanation":"Predicting the effect of a change on a food web requires analysis and reasoning about relationships, unlike recall questions.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-217","question":"A teacher asks Class 6 students to estimate the number of beans in a jar before counting them, and then discuss how close each estimate was and how they made it. The main value of this activity is that it:","options":["Develops estimation strategies and number sense, such as using a sample to judge the whole","Teaches exact counting","Is a time-filler with no maths value","Helps the teacher find the fastest counter"],"answer":0,"explanation":"Estimating and comparing strategies (counting a layer and multiplying, for example) builds number sense and reasoning about quantity that exact calculation alone does not.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-218","question":"How many of these statements about the Van Hiele model are correct? I. The levels are sequential, so a learner cannot reach a level without passing through the earlier ones. II. Progress from one level to the next depends more on instruction and experience than on age. III. If a teacher teaches at a level above the learners’, they may only memorise without understanding. IV. All children reach the deduction level automatically by the age of 12.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III reflect the Van Hieles’ view. Advancement is not automatic with age, so IV is false; many adults never reach formal deduction.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-219","question":"Assertion (A): Children who are taught the long-division algorithm as a set of steps, without understanding, often make errors such as leaving out zeros in the quotient. Reason (R): Standard algorithms are efficient methods for calculation.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both statements are true, but efficiency does not explain the errors; they arise because the steps are followed without understanding of place value and of what each step means.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-220","question":"A Class 3 child writes 7 × 0 = 7. Which approach best helps the child understand the correct answer?","options":["Telling the child the rule ‘anything times zero is zero’","Asking the child to write the zero table ten times","Asking the child to use a calculator","Using a story such as ‘7 plates with no laddoos on each plate; how many laddoos in all?’ and linking it to repeated addition"],"answer":3,"explanation":"Seeing 7 × 0 as 7 groups of nothing (0 + 0 + … + 0) shows why the product is 0; the error often comes from treating ×0 like +0.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-221","question":"A Class 5 child writes 0.5 + 0.25 = 0.30. What has the child most likely done?","options":["Treated the digits after the decimal point as whole numbers and added 5 + 25, ignoring place value; the correct sum is 0.75","Added correctly but forgot to carry; the correct sum is 0.80","Subtracted instead of added; the correct sum is 0.25","Misread 0.25 as 0.025; the correct sum is 0.525"],"answer":0,"explanation":"0.5 is 5 tenths, which is 50 hundredths; 50 + 25 = 75 hundredths = 0.75. Money (₹0.50 + ₹0.25) or a hundred-square makes the place values visible.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-222","question":"A Class 2 child insists that a large balloon must be heavier than a small stone. The best way to address this is to:","options":["Tell the child that size and weight are different","Let the child compare them on a simple balance and discuss what she sees","Ask the child to draw both objects","Explain the meaning of mass"],"answer":1,"explanation":"Young children often judge weight by size; direct comparison on a balance gives evidence that challenges the idea and builds the concept of weight.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-223","question":"A Class 6 student says that any arrangement of six joined squares can be folded into a cube. The best teaching response is to:","options":["Tell the student that only some arrangements work and give the list","Show a finished cube and move on","Let students draw different six-square arrangements, predict which will fold into a cube, then cut and fold to check and discuss why some fail","Ask students to memorise the faces, edges and vertices of a cube"],"answer":2,"explanation":"Predicting and testing nets develops spatial visualisation and reasoning; students discover that only some arrangements (11 in all) fold into a cube and can explain why others overlap.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-224","question":"A child says, ‘Maths makes sense to me. If I keep trying, I can work out problems.’ Among the strands of mathematical proficiency (conceptual understanding, procedural fluency, strategic competence, adaptive reasoning and productive disposition), this mainly reflects:","options":["Procedural fluency","Strategic competence","Adaptive reasoning","Productive disposition"],"answer":3,"explanation":"Productive disposition is seeing mathematics as sensible and worthwhile and believing in one’s own effort; it supports and is supported by the other strands.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-225","question":"A teacher takes a common wrong solution from the class test, removes the name, puts it on the board and asks students to find and explain the mistake. The main value of this practice is that it:","options":["Uses errors as a resource for learning, prompting students to analyse reasoning and confront a common misconception","Embarrasses students who make mistakes","Saves the teacher from correcting copies","Shows students which answers will lose marks"],"answer":0,"explanation":"NCF 2005 urges teachers to treat errors as windows into thinking; analysing an anonymous error is safe and makes the misconception explicit for everyone.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-226","question":"A Class 4 teacher plans a ‘water’ theme in which children sing songs about rain in language class, measure rainfall in mathematics, and study water sources in EVS. This approach is called:","options":["The subject-centred approach","The thematic (integrated) approach","The lecture method","The project method in its original form"],"answer":1,"explanation":"A thematic approach organises learning across subjects around one theme, helping children see knowledge as connected rather than in separate compartments.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-227","question":"NCERT’s Learning Outcomes for the elementary stage (2017) for EVS are best described as:","options":["A list of chapters to be completed in each class","A set of questions to be asked in the final examination","Process-based statements of what children should be able to do at the end of each class, which act as checkpoints for assessing learning","Guidelines on school infrastructure"],"answer":2,"explanation":"Learning outcomes describe what children should be able to do (e.g. ‘identifies simple features of animals’, ‘records observations’), guiding teaching and assessment rather than listing content.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-228","question":"A Class 3 child says a seed is ‘non-living, because it does not move or eat’. Which activity best challenges this idea?","options":["Telling the child that seeds are living","Showing a picture of a tree","Asking the child to memorise the features of living things","Soaking some seeds and keeping others dry, observing them for a week, and discussing why only some sprouted"],"answer":3,"explanation":"Watching soaked seeds swell and germinate shows that a seed holds a living embryo that grows under suitable conditions, giving evidence instead of a statement.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-229","question":"A Class 6 student predicts that a magnet will attract ‘all metals’. The best activity to test this is to let students:","options":["Test a steel spoon, an aluminium foil ball, a copper wire and a brass key with a magnet, record the results, and revise the rule","Read the textbook definition of magnetic materials","Watch the teacher pick up iron nails with a magnet","Memorise a list of magnetic materials"],"answer":0,"explanation":"Testing several metals shows that only some (iron, steel, nickel, cobalt) are attracted, while aluminium, copper and brass are not, so students revise the overgeneralisation from evidence.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-230","question":"In an EVS lesson on local self-government, Class 5 children role-play a gram sabha meeting where villagers discuss a broken hand pump. The main learning purpose is to help children:","options":["Memorise the names of panchayat officials","Understand how people take part in decisions about common resources, and experience discussion and differing viewpoints","Practise acting for the annual day","Learn that only elected members can speak"],"answer":1,"explanation":"Role-play makes democratic processes concrete and lets children experience participation, negotiation and civic responsibility.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-231","question":"Assertion (A): NCF 2005 treats the multilingual nature of Indian classrooms as a resource for learning. Reason (R): Research links bilingual proficiency with cognitive flexibility, greater awareness of language, and good academic achievement.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"NCF 2005 cites research associating bilingualism with cognitive growth and scholastic achievement, which is why it urges teachers to use children’s languages as a resource.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-232","question":"Before reading a story titled ‘The Lost Kite’, a teacher shows the cover picture and asks, ‘What do you think will happen in this story?’ This is an example of a:","options":["While-reading comprehension check","Post-reading evaluation activity","Pre-reading activity to activate prior knowledge and set a purpose","Grammar exercise"],"answer":2,"explanation":"Predicting from the title and pictures before reading arouses interest, activates what children know and gives them a purpose for reading.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-233","question":"Match each writing activity with the stage of the process approach it belongs to: 1. Drawing a mind-map of ideas 2. Writing a first version quickly without worrying about errors 3. Changing the order of ideas after peer feedback 4. Correcting spelling and punctuation before display; a. Revising b. Editing c. Pre-writing d. Drafting","options":["1-c, 2-a, 3-d, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":3,"explanation":"Planning ideas is pre-writing, the first version is drafting, changing content and organisation is revising, and correcting surface errors is editing.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-234","question":"Which approach to spelling is most effective for Class 3 children?","options":["Learning a list of 20 unrelated words by heart every week","Writing each misspelt word 50 times","Exploring word families and sound patterns (cat, hat, mat; night, light, right) and using words from children’s own writing","Avoiding any attention to spelling until Class 5"],"answer":2,"explanation":"Spelling develops through noticing patterns and meaningful use; rote lists and punitive repetition rarely transfer to children’s actual writing.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-235","question":"To assess the listening comprehension of Class 1 children, a teacher reads a short story aloud and asks them to put four picture cards from the story in order. Why is this a suitable task?","options":["It tests handwriting along with listening","It is easier to mark than an oral test","It shows which children can read the cards","It assesses understanding of what was heard without depending on reading or writing skills the children may not yet have"],"answer":3,"explanation":"A valid listening test should not be contaminated by other skills; sequencing pictures lets young children show comprehension directly.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-236","question":"Regular use of short dramas and dialogues in a Class 4 English class mainly helps children to:","options":["Memorise grammar rules","Use language in meaningful situations, building fluency and confidence in speaking","Improve their handwriting","Prepare for written examinations only"],"answer":1,"explanation":"Drama provides context, purpose and emotion for language use, lowering anxiety and developing spoken fluency.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-237","question":"A child who speaks a regional dialect at home is laughed at by classmates for ‘speaking wrongly’. The most appropriate response of a language teacher is to:","options":["Explain that all dialects are rule-governed, legitimate forms of language, value the child’s speech, and help children learn the standard variety for situations that need it","Tell the child to stop using the dialect in school","Correct the child’s speech in front of the class","Ignore the incident"],"answer":0,"explanation":"Linguistically, dialects are systematic, not ‘wrong’; respecting them protects children’s identity and confidence, while the standard form can be added for formal use.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-238","question":"A teacher writes ‘happy, unhappy, happiness, happily’ on the board and asks children to find other words that change in the same way. This activity mainly develops:","options":["Phonemic awareness","Handwriting","Morphological awareness: understanding how prefixes and suffixes build words and change meaning","Listening skill"],"answer":2,"explanation":"Knowing how word parts combine helps children work out the meanings of many new words, a strong support for vocabulary and reading.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-239","question":"Kenneth Goodman described reading as a ‘psycholinguistic guessing game’. This view implies that skilled readers:","options":["Read every letter of every word in strict order","Use their knowledge of language and the world to predict and confirm meaning, sampling only as much print as they need","Read mainly by memorising whole texts","Depend only on phonics rules"],"answer":1,"explanation":"Goodman’s top-down view sees reading as an active process of predicting, sampling and confirming meaning, in contrast to a purely letter-by-letter (bottom-up) process.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-240","question":"Which question asked by a teacher in an English class is a ‘referential’ question rather than a ‘display’ question?","options":["‘What is the past tense of “go”?’","‘Who wrote this story?’","‘How many characters are there in the story?’","‘What would you have done if you were in the boy’s place?’"],"answer":3,"explanation":"Display questions ask for answers the teacher already knows, to check knowledge; referential questions seek genuine information or opinion and lead to more authentic communication.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-241","question":"Which practice is most in line with NEP 2020’s guidance on languages in the classroom?","options":["Punishing children for speaking their home language in school","Using only English textbooks from the foundational stage","Using bilingual teaching–learning materials and a bilingual approach where the home language differs from the medium of instruction","Teaching the home language only as an optional subject after Class 8"],"answer":2,"explanation":"NEP 2020 encourages teachers to use a bilingual approach, including bilingual materials, for students whose home language differs from the medium of instruction.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-242","question":"Class 6 students measure the distance around and across several round objects (bangles, plates, lids) and find that the ratio is close to 3.1 every time. The main value of this activity is that it:","options":["Proves the exact value of π","Shows that measurement is always inaccurate","Replaces the need to learn the formula","Lets students discover that the circumference is always a little more than three times the diameter, giving meaning to π before the formula"],"answer":3,"explanation":"Measuring many circles shows a constant ratio, making π a discovered relationship rather than a memorised number; measurement cannot prove its exact value.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-243","question":"A Class 6 student says 6 ÷ 1/2 = 3. Which question best helps the student make sense of the correct answer?","options":["‘How many half-rotis can you make from 6 rotis?’","‘What is half of 6?’","‘What is the rule for dividing by a fraction?’","‘What is 6 × 2?’"],"answer":0,"explanation":"The student has found half of 6. Interpreting division as ‘how many halves fit into 6’ shows that the answer is 12 and gives meaning to the invert-and-multiply rule.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-244","question":"A shopkeeper gives change for a ₹100 note on a ₹63 purchase by saying ‘63… 64, 65, 70, 100’ while handing over ₹1, ₹1, ₹5 and ₹30. Using this method in class mainly helps children to understand:","options":["Multiplication of money","Subtraction as finding the difference by counting up (adding on)","Division into equal shares","Rounding to the nearest ten"],"answer":1,"explanation":"Counting up from the smaller number to the larger is a powerful informal strategy for subtraction (100 − 63 = 37) that connects school maths to everyday practice.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-245","question":"A Class 5 child says that when a wet cloth dries, ‘the water just goes into the cloth and disappears’. Which activity best helps the child build the idea of evaporation?","options":["Telling the child that water becomes vapour","Showing a diagram of the water cycle","Keeping two plates of water, one covered and one open, in the sun and comparing them, and then holding a cold glass to see droplets form from the air","Asking the child to memorise the definition of evaporation"],"answer":2,"explanation":"The open plate loses water while the covered one does not, showing water goes into the air; droplets on a cold glass show the water vapour is still there. Evidence builds the idea that water changes state rather than vanishing.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-246","question":"A teacher uses phonics drills to build word recognition and also asks children to predict words from the story context and pictures. Which statement best describes this?","options":["It is purely a bottom-up approach to reading","It is purely a top-down approach to reading","It mixes up two incompatible methods and will confuse children","It reflects an interactive model, combining bottom-up decoding with top-down use of context and prior knowledge"],"answer":3,"explanation":"Interactive models hold that readers use letter–sound information and contextual knowledge together; good teaching develops both.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-247","question":"A Class 8 student writes (a + b)² = a² + b². Which activity best helps the student see why this is wrong?","options":["Drawing a square of side (a + b), dividing it into a², b² and two a × b rectangles, and checking with a = 3, b = 2 (25 compared with 13)","Making the student memorise the identity","Telling the student that brackets cannot be removed","Giving ten more expansions to practise"],"answer":0,"explanation":"The area model shows the two missing ab rectangles, and the numerical check (5² = 25, but 9 + 4 = 13) confirms it, building understanding instead of rote recall.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-248","question":"In an EVS lesson on houses, a child from a migrant family says her family has lived in a tent, a hut and now a room in the city. The teacher should:","options":["Move on quickly to avoid embarrassing the child","Invite her to share her experience as a valuable example of how and why people’s shelters change","Tell the class that tents are not real houses","Ask her to describe the house in the textbook instead"],"answer":1,"explanation":"Children’s varied lives are rich resources for EVS; valuing them builds inclusion and helps all children understand the links between shelter, livelihood and migration.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-249","question":"Class 4 children find it hard to read maps. The teacher asks them to draw how a pencil box, a bottle and a book on the desk look from directly above. The main purpose of this activity is to develop:","options":["Drawing skills for the art period","Knowledge of map symbols","The idea of a top (bird’s-eye) view, which is the basis for understanding maps","Measurement of length"],"answer":2,"explanation":"Maps show places as seen from above; drawing top views of familiar objects helps children make the shift from side views to the plan view that maps use.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-250","question":"A Class 7 student with a locomotor disability uses a wheelchair. Which arrangement best supports her in science practicals?","options":["Letting her only watch while others perform the experiments","Providing a work table at an accessible height, keeping apparatus within reach, and giving her a full share of hands-on roles in the group","Asking her to write the record while others do the practical","Exempting her from practical assessment"],"answer":1,"explanation":"Reasonable accommodation, such as accessible furniture and placement of apparatus, lets her take part fully; being only an observer or recorder denies her the practical learning.","difficulty":"moderate","source":"CTET Paper II · KVS · DSSSB"},
];

export default questions;
